window.FAQ=(window.FAQ||[]).concat([
 {id:'kvx-001',thema:'krediet-vermogen',vraag:'Wat doe ik als een klant zegt geen kredieten te hebben maar de BKR-toets toont er wel een?',antwoord:`Bespreek het verschil direct met de klant en vraag om uitleg. Vaak gaat het om een vergeten creditcard, een oude limiet of een lease-contract. Vraag een eigen BKR-overzicht en een actueel saldo-overzicht van de kredietgever op. Leg vast hoe het verschil is ontstaan en hoe het is opgelost.`,tags:['BKR','verschil','opgave klant','dossier'],bron:'BKR'},
 {id:'kvx-002',thema:'krediet-vermogen',vraag:'Hoe ga ik om met een BKR-registratie van een krediet dat al is overgesloten?',antwoord:`Bij oversluiten ontstaat meestal een nieuwe registratie en wordt de oude als beëindigd gemeld. Soms staat de oude registratie nog tijdelijk als lopend in het overzicht. Vraag een bevestiging van de kredietgever dat het oude krediet is afgelost. Zo voorkomt u dat een last dubbel meetelt in de toetsing.`,tags:['BKR','oversluiten','dubbeltelling'],bron:'BKR'},
 {id:'kvx-003',thema:'krediet-vermogen',vraag:'Telt een BKR-registratie van de partner mee als die niet mee-aanvraagt?',antwoord:`Dat hangt af van de situatie en de geldverstrekker. Bij een gezamenlijke aanvraag tellen de lasten van beide aanvragers mee. Is de partner geen aanvrager, dan kan diens krediet toch relevant zijn, bijvoorbeeld bij een gezamenlijk huishouden of gemeenschap van goederen. Controleer de acceptatievoorwaarden van de geldverstrekker en leg uw afweging vast.`,tags:['BKR','partner','aanvraag'],bron:''},
 {id:'kvx-004',thema:'krediet-vermogen',vraag:'Wat is het verschil tussen een BKR-toets en een BKR-overzicht dat de klant zelf opvraagt?',antwoord:`De geldverstrekker toetst rechtstreeks in het CKI op het moment van aanvraag. Het overzicht dat de klant zelf opvraagt is een momentopname voor eigen gebruik. Het eigen overzicht is handig voor een eerste inventarisatie in het oriëntatiegesprek. Het vervangt de toets van de geldverstrekker niet.`,tags:['BKR','inzage','toetsing'],bron:'BKR'},
 {id:'kvx-005',thema:'krediet-vermogen',vraag:'Mag ik als adviseur zelf het BKR raadplegen voor een klant?',antwoord:`Een adviseur heeft doorgaans geen eigen toegang tot het CKI zoals een kredietgever die heeft. De gangbare route is dat de klant zelf inzage opvraagt en deze deelt. Vraag daarvoor toestemming en bewaar het overzicht volgens uw privacybeleid. Bewaar niet meer gegevens dan nodig voor het advies.`,tags:['BKR','inzage','privacy','AVG'],bron:'AVG'},
 {id:'kvx-006',thema:'krediet-vermogen',vraag:'Wat betekent een registratie van een schuldregeling in het CKI voor een hypotheekaanvraag?',antwoord:`Een gemelde schuldregeling is voor de meeste geldverstrekkers een zwaar signaal. Ook na afronding blijft de melding nog een periode zichtbaar. Acceptatie is dan vaak alleen mogelijk via maatwerk, als dat al kan. Leg de achtergrond en de huidige financiële situatie zorgvuldig vast.`,tags:['BKR','schuldregeling','acceptatie'],bron:'BKR'},
 {id:'kvx-007',thema:'krediet-vermogen',vraag:'Hoe beoordeel ik een achterstand die door een eenmalige gebeurtenis is ontstaan?',antwoord:`Breng de oorzaak, de duur en het herstel van de achterstand in kaart. Denk aan een ziekteperiode of een tijdelijk inkomensverlies. Vraag bewijsstukken op die de oorzaak en het herstel ondersteunen. Sommige geldverstrekkers beoordelen dit via een maatwerkaanvraag met een toelichting.`,tags:['BKR','achterstand','maatwerk','toelichting'],bron:''},
 {id:'kvx-008',thema:'krediet-vermogen',vraag:'Welke toelichting stuur ik mee bij een maatwerkaanvraag met een BKR-codering?',antwoord:`Een goede toelichting is feitelijk en kort. Neem op:
- wat de oorzaak van de achterstand was
- wanneer en hoe die is opgelost
- waarom de situatie nu stabiel is
- welke bewijsstukken dit onderbouwen
Laat de klant de toelichting controleren en bewaar een kopie in het dossier.`,tags:['BKR','maatwerk','toelichting','dossier'],bron:''},
 {id:'kvx-009',thema:'krediet-vermogen',vraag:'Wordt een hypotheek ook in het CKI geregistreerd?',antwoord:`Ja, hypotheken worden in het CKI geregistreerd. Een lopende hypotheek is dus zichtbaar voor andere kredietgevers. Een betalingsachterstand op een hypotheek kan ook worden gemeld. Dit is van belang bij een tweede woning of een oversluiting naar een andere geldverstrekker.`,tags:['BKR','hypotheek','registratie'],bron:'BKR'},
 {id:'kvx-010',thema:'krediet-vermogen',vraag:'Wat als een klant een kredietaanvraag heeft gedaan die is afgewezen?',antwoord:`Een afgewezen aanvraag op zich leidt niet tot een kredietregistratie. Wel kan een klant met veel recente aanvragen een signaal geven over zijn financiële situatie. Vraag in het gesprek naar recente aanvragen en de reden. Leg vast wat de klant hierover vertelt.`,tags:['BKR','aanvraag','afwijzing'],bron:'BKR'},
 {id:'kvx-011',thema:'krediet-vermogen',vraag:'Hoe ga ik om met een creditcard die de klant nooit gebruikt?',antwoord:`Ook een ongebruikte creditcard met een limiet kan meetellen in de toetsing. Het gaat om de geregistreerde limiet, niet om het gebruik. Bespreek of de klant de kaart wil opzeggen. Vraag na opzegging een bevestiging dat de registratie als beëindigd wordt gemeld.`,tags:['creditcard','limiet','opzeggen'],bron:''},
 {id:'kvx-012',thema:'krediet-vermogen',vraag:'Wanneer is het zinvol om een doorlopend krediet te verlagen in plaats van op te zeggen?',antwoord:`Verlagen kan zinvol zijn als de klant een kleine reserve wil houden. De toetsingslast daalt dan, maar verdwijnt niet. Opzeggen haalt de last volledig uit de toetsing, mits de registratie als beëindigd is gemeld. Leg de keuze van de klant en de gevolgen voor de leencapaciteit vast.`,tags:['doorlopend krediet','limiet','leencapaciteit'],bron:''},
 {id:'kvx-013',thema:'krediet-vermogen',vraag:'Wat is het verschil tussen een aflopend en een doorlopend krediet voor de toetsing?',antwoord:`Bij een aflopend krediet ligt de maandtermijn en looptijd vast. Bij een doorlopend krediet kan de klant opnieuw opnemen tot de limiet. Daarom wordt bij een doorlopend krediet meestal gerekend met een vast percentage van de limiet. Bij een aflopend krediet is de werkelijke termijn of de regeling van de geldverstrekker leidend.`,tags:['aflopend krediet','doorlopend krediet','toetsing'],bron:'Tijdelijke regeling hypothecair krediet'},
 {id:'kvx-014',thema:'krediet-vermogen',vraag:'Hoe beoordeel ik een krediet dat binnenkort volledig is afgelost?',antwoord:`Een krediet dat nog loopt telt in principe mee in de toetsing. Sommige geldverstrekkers maken een uitzondering als de resterende looptijd kort is. Controleer de voorwaarden van de geldverstrekker. Vraag een recent overzicht met het restsaldo en de einddatum op.`,tags:['krediet','restschuld','looptijd'],bron:''},
 {id:'kvx-015',thema:'krediet-vermogen',vraag:'Is een koop op afbetaling bij een webwinkel een krediet?',antwoord:`Ja, kopen op afbetaling is vaak een vorm van consumptief krediet. Afhankelijk van bedrag en looptijd kan het in het CKI worden geregistreerd. Vraag klanten ook naar dit soort regelingen, omdat ze het zelf niet altijd als lening zien. Leg de opgave vast.`,tags:['afbetaling','consumptief krediet','inventarisatie'],bron:'Wft'},
 {id:'kvx-016',thema:'krediet-vermogen',vraag:'Telt achteraf betalen mee als krediet?',antwoord:`Achteraf betalen wordt steeds strenger gereguleerd en kan onder het kredietregime vallen. Of het in het CKI zichtbaar is, hangt af van de aanbieder en de regelgeving op dat moment. Vraag klanten actief naar openstaande bedragen via achteraf betalen. Structureel gebruik kan een signaal zijn over het bestedingspatroon.`,tags:['achteraf betalen','krediet','inventarisatie'],bron:''},
 {id:'kvx-017',thema:'krediet-vermogen',vraag:'Hoe weeg ik een financial lease van een auto voor een particulier?',antwoord:`Bij financial lease wordt de klant uiteindelijk eigenaar van de auto. Het is een vorm van krediet en telt mee als financiële verplichting. Vraag het contract op met de maandtermijn en de resterende looptijd. Let ook op een eventuele slottermijn aan het einde.`,tags:['financial lease','auto','krediet'],bron:''},
 {id:'kvx-018',thema:'krediet-vermogen',vraag:'Wat is het verschil tussen private lease en financial lease voor de toetsing?',antwoord:`Bij private lease huurt de klant de auto en wordt hij geen eigenaar. Bij financial lease is er sprake van een krediet met eigendomsoverdracht. Beide kunnen in het CKI geregistreerd staan en meetellen. Controleer hoe de geldverstrekker de maandlast meeneemt.`,tags:['private lease','financial lease','toetsing'],bron:'BKR'},
 {id:'kvx-019',thema:'krediet-vermogen',vraag:'Hoe ga ik om met een slottermijn in een autofinanciering?',antwoord:`Een slottermijn betekent dat er aan het einde nog een groot bedrag openstaat. Bespreek met de klant hoe hij die slottermijn wil betalen. Dat kan invloed hebben op zijn buffer en toekomstige leencapaciteit. Leg de afspraak en de risico-inschatting vast.`,tags:['slottermijn','autofinanciering','buffer'],bron:''},
 {id:'kvx-020',thema:'krediet-vermogen',vraag:'Kan een consumptief krediet worden meegefinancierd in de hypotheek?',antwoord:`Technisch kan een geldverstrekker toestaan dat een krediet uit de hypotheek wordt afgelost. Fiscaal is dat deel geen eigenwoningschuld, omdat het niet voor de woning is gebruikt. De rente is dan niet aftrekbaar en de schuld valt in box 3. Controleer de voorwaarden van de geldverstrekker en leg de fiscale gevolgen uit.`,tags:['krediet','hypotheek','box 3','eigenwoningschuld'],bron:'Wet IB 2001'},
 {id:'kvx-021',thema:'krediet-vermogen',vraag:'Wat moet ik vastleggen als een klant een krediet oversluit naar de hypotheek?',antwoord:`Leg vast waarom de klant hiervoor kiest en welke alternatieven zijn besproken. Vermeld dat het deel geen eigenwoningschuld is en de rente niet aftrekbaar. Bespreek ook dat een korte kredietschuld nu over een lange looptijd wordt verspreid. Dat kan de totale rentelast verhogen.`,tags:['oversluiten','dossier','rentelast'],bron:''},
 {id:'kvx-022',thema:'krediet-vermogen',vraag:'Wat is het herroepingsrecht bij een consumptief krediet?',antwoord:`Een consument heeft bij een kredietovereenkomst een wettelijke bedenktijd van 14 kalenderdagen. In die periode kan hij zonder opgave van redenen afzien van het krediet. Hij betaalt dan wel het opgenomen bedrag en de rente over die periode terug. Wijs klanten hierop als zij een krediet nog net hebben afgesloten.`,tags:['herroepingsrecht','bedenktijd','consumptief krediet'],bron:'BW'},
 {id:'kvx-023',thema:'krediet-vermogen',vraag:'Mag een consumptief krediet altijd vervroegd worden afgelost?',antwoord:`Een consument heeft het recht om een krediet geheel of gedeeltelijk vervroegd af te lossen. Bij een vaste rente mag de kredietgever onder voorwaarden een beperkte vergoeding vragen. Bij een doorlopend krediet geldt dat meestal niet. Controleer de voorwaarden van de kredietgever.`,tags:['vervroegd aflossen','consumptief krediet','vergoeding'],bron:'BW'},
 {id:'kvx-024',thema:'krediet-vermogen',vraag:'Is er een maximum aan de rente op een consumptief krediet?',antwoord:`Ja, in Nederland geldt een wettelijk maximum voor de kredietvergoeding. Dit maximum is gekoppeld aan de wettelijke rente en kan dus wijzigen. Gebruik voor actuele cijfers de officiële bronnen. Een zeer hoge rente kan aanleiding zijn om oversluiten of aflossen te bespreken.`,tags:['kredietvergoeding','maximum','rente'],bron:'Besluit kredietvergoeding'},
 {id:'kvx-025',thema:'krediet-vermogen',vraag:'Welke rol speelt de VFN bij consumptief krediet?',antwoord:`De VFN is de brancheorganisatie van consumptief-kredietverstrekkers. Leden hanteren gedragsregels en een gemeenschappelijke toetsingsmethode voor verantwoord lenen. Voor de hypotheektoets zijn die normen niet leidend. Het is wel nuttig om te weten hoe een kredietgever de klant beoordeelt.`,tags:['VFN','gedragscode','verantwoord lenen'],bron:'VFN'},
 {id:'kvx-026',thema:'krediet-vermogen',vraag:'Wanneer is een consumptief krediet een rood signaal in het adviesgesprek?',antwoord:`Signalen zijn bijvoorbeeld:
- meerdere kredieten tegelijk
- kredieten om vaste lasten te betalen
- structureel rood staan
- recent afgesloten kredieten vlak voor de aanvraag
Bespreek deze punten open en leg vast hoe u ze heeft beoordeeld.`,tags:['signalen','krediet','zorgplicht'],bron:''},
 {id:'kvx-027',thema:'krediet-vermogen',vraag:'Hoe bespreek ik een krediet dat de klant voor de woning wil afsluiten na het passeren?',antwoord:`Een krediet kort na passeren kan de betaalbaarheid onder druk zetten. De hypotheektoets houdt dan geen rekening met die extra last. Bespreek de gevolgen voor het maandbudget en de buffer. Leg vast dat u dit heeft besproken en wat de klant van plan is.`,tags:['krediet','na passeren','betaalbaarheid'],bron:''},
 {id:'kvx-028',thema:'krediet-vermogen',vraag:'Kan een verbouwing beter met een krediet of met een hypotheekverhoging worden gefinancierd?',antwoord:`Bij een hypotheekverhoging voor verbetering van de woning kan de rente aftrekbaar zijn, mits aan de voorwaarden wordt voldaan. Een consumptief krediet valt in box 3 en de rente is niet aftrekbaar. Daar staan andere factoren tegenover, zoals kosten en flexibiliteit. Maak de afweging inzichtelijk en leg die vast.`,tags:['verbouwing','hypotheekverhoging','krediet'],bron:'Wet IB 2001'},
 {id:'kvx-029',thema:'krediet-vermogen',vraag:'Hoe toon ik aan dat een krediet voor de woning is besteed?',antwoord:`Bewaar facturen, offertes en betaalbewijzen van de verbouwing. Dit is van belang als het krediet later wordt omgezet naar eigenwoningschuld. Zonder bewijs is de fiscale kwalificatie lastig te onderbouwen. Adviseer de klant deze stukken te bewaren.`,tags:['bewijs','verbouwing','eigenwoningschuld'],bron:'Belastingdienst'},
 {id:'kvx-030',thema:'krediet-vermogen',vraag:'Telt een geregistreerd krediet mee als het via een werkgever loopt?',antwoord:`Een lening van een werkgever staat niet altijd in het CKI. Toch is het een financiële verplichting met een maandlast. Vraag naar zulke leningen en naar de voorwaarden. Leg de afspraak vast en controleer hoe de geldverstrekker ermee omgaat.`,tags:['werkgever','lening','inventarisatie'],bron:''},
 {id:'kvx-031',thema:'krediet-vermogen',vraag:'Hoe ga ik om met een betalingsregeling bij de Belastingdienst?',antwoord:`Een betalingsregeling bij de Belastingdienst staat meestal niet in het CKI. Het is wel een verplichting die het maandbudget drukt. Vraag de klant naar lopende regelingen en de resterende looptijd. Controleer of de geldverstrekker deze verplichting meetelt.`,tags:['betalingsregeling','Belastingdienst','verplichting'],bron:''},
 {id:'kvx-032',thema:'krediet-vermogen',vraag:'Wat is het risico als een klant een lening verzwijgt?',antwoord:`Een verzwegen verplichting kan leiden tot een te hoge hypotheek en betalingsproblemen. De klant kan bovendien in strijd handelen met de mededelingsplicht in de aanvraag. Voor de adviseur is het van belang dat hij er actief naar heeft gevraagd. Leg de opgave van de klant schriftelijk vast en laat die bevestigen.`,tags:['verzwijgen','mededelingsplicht','dossier'],bron:''},
 {id:'kvx-033',thema:'krediet-vermogen',vraag:'Hoe stel ik vragen naar kredieten zonder dat het een verhoor wordt?',antwoord:`Werk met een vaste checklist die u bij iedere klant gebruikt. Leg uit waarom u het vraagt: het gaat om een verantwoord advies. Noem concrete voorbeelden zoals creditcards, lease, afbetaling en familieleningen. Zo vergeten klanten minder en voelt het niet persoonlijk.`,tags:['inventarisatie','gesprekstechniek','checklist'],bron:''},
 {id:'kvx-034',thema:'krediet-vermogen',vraag:'Wat is de betekenis van de einddatum in het CKI-overzicht?',antwoord:`De einddatum geeft aan wanneer een krediet is beëindigd. Na die datum blijft de registratie nog een periode zichtbaar. Een geldverstrekker ziet daardoor ook recent afgeloste kredieten. Controleer bij twijfel of de status als beëindigd juist is verwerkt.`,tags:['BKR','einddatum','status'],bron:'BKR'},
 {id:'kvx-035',thema:'krediet-vermogen',vraag:'Wat doe ik als een kredietgever een beëindiging te laat aan het BKR meldt?',antwoord:`Vraag de klant om de kredietgever te verzoeken de status te actualiseren. Vraag ook een schriftelijke bevestiging van de aflossing. Die bevestiging kan bij de geldverstrekker vaak al worden gebruikt. Leg de communicatie vast in het dossier.`,tags:['BKR','beëindiging','correctie'],bron:'BKR'},
 {id:'kvx-036',thema:'krediet-vermogen',vraag:'Waar kan een klant terecht als de kredietgever een BKR-registratie niet wil aanpassen?',antwoord:`De klant kan eerst een klacht indienen bij de kredietgever. Daarna is een klacht bij het Kifid mogelijk als de kredietgever daar is aangesloten. Een rechter is ook een optie. Adviseer de klant de procedure van de kredietgever te volgen en alles te bewaren.`,tags:['BKR','klacht','Kifid'],bron:'Kifid'},
 {id:'kvx-037',thema:'krediet-vermogen',vraag:'Is een BKR-registratie een reden om geen advies te geven?',antwoord:`Nee, een registratie is geen reden om advies te weigeren. Het is wel een reden om zorgvuldig te onderzoeken wat haalbaar is. Soms is het advies om eerst te wachten of de situatie te verbeteren. Dat advies is net zo waardevol, mits u het goed vastlegt.`,tags:['BKR','advies','zorgplicht'],bron:''},
 {id:'kvx-038',thema:'krediet-vermogen',vraag:'Hoe weeg ik een krediet van een ondernemer dat op privénaam staat?',antwoord:`Een zakelijk krediet op privénaam kan in het CKI geregistreerd staan. Voor de toetsing is van belang wie de lasten draagt en of de onderneming die betaalt. Geldverstrekkers gaan hier verschillend mee om. Vraag het contract en de jaarcijfers op en controleer de voorwaarden van de geldverstrekker.`,tags:['ondernemer','zakelijk krediet','toetsing'],bron:''},
 {id:'kvx-039',thema:'krediet-vermogen',vraag:'Telt een borgstelling voor een ander mee als verplichting?',antwoord:`Een borgstelling is een mogelijke verplichting. Als de hoofdschuldenaar niet betaalt, kan de borg worden aangesproken. Niet iedere borgstelling is zichtbaar in het CKI. Vraag er actief naar en controleer hoe de geldverstrekker ermee omgaat.`,tags:['borgstelling','verplichting','risico'],bron:'BW'},
 {id:'kvx-040',thema:'krediet-vermogen',vraag:'Hoe ga ik om met een gezamenlijke lening na een scheiding?',antwoord:`Na een scheiding blijven beide ex-partners vaak hoofdelijk aansprakelijk voor een gezamenlijke lening. Ook als in het convenant staat dat één partner betaalt. Een geldverstrekker kan de lening dan bij beide aanvragers meetellen. Vraag het convenant op en onderzoek of ontslag uit hoofdelijkheid mogelijk is.`,tags:['scheiding','hoofdelijkheid','krediet'],bron:''},
 {id:'kvx-041',thema:'krediet-vermogen',vraag:'Wat is de rol van de kredietgever bij ontslag uit hoofdelijkheid voor een consumptief krediet?',antwoord:`Alleen de kredietgever kan een ex-partner ontslaan uit de hoofdelijke aansprakelijkheid. Hij beoordeelt of de achterblijvende partner de lening alleen kan dragen. Een afspraak tussen ex-partners bindt de kredietgever niet. Vraag de schriftelijke bevestiging van het ontslag op.`,tags:['hoofdelijkheid','scheiding','kredietgever'],bron:''},
 {id:'kvx-042',thema:'krediet-vermogen',vraag:'Wat moet ik weten over minnelijke schuldhulpverlening bij een adviesvraag?',antwoord:`Bij minnelijke schuldhulpverlening maakt een schuldhulpverlener afspraken met schuldeisers. Tijdens zo een traject is een nieuwe hypotheek in de regel niet haalbaar. Bespreek met de klant de afronding van het traject en de periode daarna. Verwijs zo nodig naar de schuldhulpverlener voor de actuele status.`,tags:['schuldhulp','minnelijk','acceptatie'],bron:''},
 {id:'kvx-043',thema:'krediet-vermogen',vraag:'Wat is het verschil tussen minnelijke schuldhulp en de Wsnp?',antwoord:`Minnelijke schuldhulp is een vrijwillige regeling met schuldeisers. De Wsnp is een wettelijke schuldsaneringsregeling via de rechter. Beide kunnen in het CKI zichtbaar zijn. De gevolgen voor de hypotheekmogelijkheden zijn vaak vergelijkbaar en langdurig.`,tags:['Wsnp','schuldsanering','schuldhulp'],bron:'Faillissementswet'},
 {id:'kvx-044',thema:'krediet-vermogen',vraag:'Hoe beoordeel ik een klant met een afgeronde Wsnp?',antwoord:`Vraag de beschikking van de rechter en het bewijs van de schone lei op. Bekijk hoe de klant sindsdien met geld omgaat. Veel geldverstrekkers hanteren nog een wachtperiode. Controleer de voorwaarden van de geldverstrekker en leg uw beoordeling vast.`,tags:['Wsnp','schone lei','acceptatie'],bron:''},
 {id:'kvx-045',thema:'krediet-vermogen',vraag:'Hoe reken ik met een krediet in een rekenvoorbeeld voor de klant?',antwoord:`Laat zien wat de leencapaciteit is met en zonder het krediet. Gebruik dezelfde uitgangspunten in beide berekeningen. Zo ziet de klant direct wat het krediet kost aan leenruimte. Vermeld dat de bedragen een indicatie zijn en afhangen van de actuele normen.`,tags:['rekenvoorbeeld','leencapaciteit','krediet'],bron:''},
 {id:'kvx-046',thema:'krediet-vermogen',vraag:'Waarom heeft een kleine kredietlimiet soms grote invloed op de hypotheek?',antwoord:`De toetsingslast van een limiet werkt door over de hele looptijd van de hypotheek. Een relatief kleine maandlast verlaagt daardoor de maximale hypotheek met een veelvoud. Laat dit in een berekening zien. Dat helpt de klant om een bewuste keuze te maken over opzeggen.`,tags:['limiet','leencapaciteit','uitleg'],bron:''},
 {id:'kvx-047',thema:'krediet-vermogen',vraag:'Hoe ga ik om met een kredietlimiet op een betaalrekening?',antwoord:`Een rood-staan-faciliteit kan als krediet in het CKI geregistreerd staan. Dan telt de limiet mee in de toetsing, ook als de klant er niet gebruik van maakt. Bespreek verlagen of opheffen. Vraag na wijziging een bevestiging van de bank.`,tags:['roodstand','limiet','BKR'],bron:'BKR'},
 {id:'kvx-048',thema:'krediet-vermogen',vraag:'Mag ik adviseren om een krediet af te lossen met spaargeld dat nodig is voor de aankoop?',antwoord:`Aflossen verhoogt de leencapaciteit, maar verlaagt de eigen middelen. Maak de berekening voor beide situaties. Let op de kosten koper en de buffer die nodig blijven. Leg vast welke afweging de klant maakt en waarom.`,tags:['aflossen','eigen middelen','afweging'],bron:''},
 {id:'kvx-049',thema:'krediet-vermogen',vraag:'Wat is de rol van de AFM bij consumptief krediet?',antwoord:`De AFM houdt toezicht op het aanbieden van en adviseren over consumptief krediet. Partijen hebben hiervoor een vergunning nodig of moeten een vrijstelling hebben. De AFM let onder meer op verantwoorde kredietverlening en informatievoorziening. Controleer of uw eigen vergunning het adviseren over krediet dekt.`,tags:['AFM','toezicht','vergunning'],bron:'AFM'},
 {id:'kvx-050',thema:'krediet-vermogen',vraag:'Welk Wft-diploma is relevant voor advies over consumptief krediet?',antwoord:`Voor advies over consumptief krediet bestaat een aparte Wft-module. Een adviseur die alleen hypotheekadvies geeft, is niet automatisch bevoegd voor kredietadvies. Controleer welke modules voor uw werkzaamheden vereist zijn. Raadpleeg hiervoor de actuele eisen van het CDFD en de AFM.`,tags:['Wft','diploma','vakbekwaamheid'],bron:'CDFD'},
 {id:'kvx-051',thema:'krediet-vermogen',vraag:'Wat is het verschil tussen het terugbetalen in 15 jaar en in 35 jaar bij DUO?',antwoord:`Het oudere stelsel kent een terugbetalingstermijn van 15 jaar. Voor studenten onder het studievoorschot en later geldt een termijn van 35 jaar. De maandlast bij 35 jaar is bij dezelfde schuld lager, maar de schuld loopt langer door. Vraag de klant welk regime op zijn schuld van toepassing is.`,tags:['studieschuld','DUO','terugbetaaltermijn'],bron:'DUO'},
 {id:'kvx-052',thema:'krediet-vermogen',vraag:'Hoe herken ik welk terugbetaalregime een klant bij DUO heeft?',antwoord:`Het regime staat in Mijn DUO en in de brieven over de terugbetaling. Het hangt vooral af van het moment waarop de studie is gestart. Vraag een schermafdruk of brief op waaruit het regime blijkt. Leg dit vast, omdat het de beoordeling van de maandlast beïnvloedt.`,tags:['studieschuld','DUO','regime','documentatie'],bron:'DUO'},
 {id:'kvx-053',thema:'krediet-vermogen',vraag:'Wat is de aanloopfase bij een studieschuld?',antwoord:`Na het einde van de studie volgt eerst een aanloopfase. In die periode hoeft de klant nog niet terug te betalen, maar loopt de rente wel door. Daarna start de terugbetaalperiode. Ook in de aanloopfase is de schuld relevant voor de hypotheektoetsing.`,tags:['studieschuld','aanloopfase','rente'],bron:'DUO'},
 {id:'kvx-054',thema:'krediet-vermogen',vraag:'Hoe beoordeel ik een studieschuld van een klant die nog in de aanloopfase zit?',antwoord:`Er is dan nog geen definitief maandbedrag. De toetsing gaat uit van een maandlast volgens de methode van de actuele regeling. Vraag bij DUO een indicatie of een overzicht van de schuld op. Controleer hoe de geldverstrekker de last bepaalt.`,tags:['studieschuld','aanloopfase','toetsing'],bron:'Tijdelijke regeling hypothecair krediet'},
 {id:'kvx-055',thema:'krediet-vermogen',vraag:'Wat is de draagkrachtregeling bij DUO?',antwoord:`Bij de draagkrachtregeling past DUO het maandbedrag aan het inkomen aan. Bij een laag inkomen kan het maandbedrag lager of zelfs nihil zijn. De schuld zelf wordt daardoor niet kleiner. Voor de hypotheektoetsing telt de regeling van de geldverstrekker, niet automatisch het verlaagde bedrag.`,tags:['draagkracht','studieschuld','DUO'],bron:'DUO'},
 {id:'kvx-056',thema:'krediet-vermogen',vraag:'Telt het inkomen van de partner mee in de draagkracht bij DUO?',antwoord:`Dat hangt af van het terugbetaalregime. Bij het oudere stelsel kan het partnerinkomen meetellen. Bij het stelsel met een termijn van 35 jaar telt het partnerinkomen niet mee. Controleer de actuele regels bij DUO.`,tags:['draagkracht','partner','studieschuld'],bron:'DUO'},
 {id:'kvx-057',thema:'krediet-vermogen',vraag:'Op welk inkomen baseert DUO de draagkracht?',antwoord:`DUO gebruikt in principe het inkomen van twee jaar eerder als peiljaar. Is het huidige inkomen lager, dan kan de klant vragen om met het actuele inkomen te rekenen. Dit is relevant als het maandbedrag niet past bij de huidige situatie. Vraag de klant de beschikking van DUO op.`,tags:['draagkracht','peiljaar','DUO'],bron:'DUO'},
 {id:'kvx-058',thema:'krediet-vermogen',vraag:'Wat zijn aflosvrije periodes bij een studieschuld?',antwoord:`Een klant kan bij DUO een beperkt aantal maanden aanvragen waarin hij niet hoeft af te lossen. De rente loopt in die periode wel door. Controleer bij DUO wat dit betekent voor de resterende terugbetaalperiode. Vraag of de klant hier gebruik van maakt, omdat het iets zegt over zijn financiële situatie.`,tags:['aflosvrije periode','studieschuld','DUO'],bron:'DUO'},
 {id:'kvx-059',thema:'krediet-vermogen',vraag:'Heeft een aflosvrije periode invloed op de hypotheektoetsing?',antwoord:`De schuld blijft bestaan, dus de studieschuld telt gewoon mee. Een tijdelijk lager of nihil maandbedrag verandert dat niet. De toetsing volgt de methode in de regeling en de voorwaarden van de geldverstrekker. Leg de periode en de reden vast in het dossier.`,tags:['aflosvrije periode','toetsing','studieschuld'],bron:''},
 {id:'kvx-060',thema:'krediet-vermogen',vraag:'Wat gebeurt met een studieschuld bij overlijden?',antwoord:`Bij overlijden scheldt DUO de resterende studieschuld kwijt. Nabestaanden erven deze schuld dus niet. Dit is relevant bij het bepalen van het risico voor een partner. Het overlijdensrisico van de hypotheek staat daar los van.`,tags:['overlijden','studieschuld','kwijtschelding'],bron:'DUO'},
 {id:'kvx-061',thema:'krediet-vermogen',vraag:'Wat gebeurt met een studieschuld aan het einde van de terugbetaalperiode?',antwoord:`Wat na afloop van de terugbetaalperiode nog openstaat, wordt kwijtgescholden. Dat geldt mits aan de voorwaarden is voldaan. Voor de klant met een laag inkomen kan dit een reden zijn om niet extra af te lossen. Maak die afweging samen met de klant en leg deze vast.`,tags:['kwijtschelding','studieschuld','terugbetaalperiode'],bron:'DUO'},
 {id:'kvx-062',thema:'krediet-vermogen',vraag:'Is de rente op een studieschuld aftrekbaar?',antwoord:`Nee, de rente op een studieschuld is niet aftrekbaar. De studieschuld valt als schuld in box 3. Daar kan zij de grondslag verlagen, maar alleen voor zover de schulden boven de schuldendrempel uitkomen. Gebruik voor de drempel het actuele bedrag van de Belastingdienst.`,tags:['studieschuld','box 3','rente'],bron:'Belastingdienst'},
 {id:'kvx-063',thema:'krediet-vermogen',vraag:'Hoe wordt de rente op een studieschuld vastgesteld?',antwoord:`DUO stelt de rente vast op basis van wettelijke regels. Bij het stelsel met 35 jaar staat de rente telkens voor een periode van vijf jaar vast. Bij het oudere stelsel kan de rente vaker wijzigen. Controleer het actuele percentage bij DUO.`,tags:['rente','studieschuld','DUO'],bron:'DUO'},
 {id:'kvx-064',thema:'krediet-vermogen',vraag:'Wanneer is extra aflossen op een studieschuld zinvol voor een hypotheekaanvraag?',antwoord:`Extra aflossen kan de toetsingslast verlagen en zo de leencapaciteit vergroten. Dat werkt alleen als het maandbedrag of de schuld voor de toetsing daadwerkelijk daalt. Vraag bij DUO na wat het effect van de aflossing is. Maak een berekening met en zonder aflossing.`,tags:['extra aflossen','studieschuld','leencapaciteit'],bron:'DUO'},
 {id:'kvx-065',thema:'krediet-vermogen',vraag:'Kost extra aflossen op een studieschuld een vergoeding?',antwoord:`Nee, extra aflossen op een studieschuld kan zonder boete. De klant kan een deel of de hele schuld in een keer aflossen. Wel gaat het geld dan niet meer naar de buffer of de eigen middelen. Bespreek die afweging.`,tags:['extra aflossen','studieschuld','boete'],bron:'DUO'},
 {id:'kvx-066',thema:'krediet-vermogen',vraag:'Hoe ga ik om met een omgezette prestatiebeurs?',antwoord:`Als een student niet tijdig een diploma haalt, kan een prestatiebeurs een lening worden. Die lening telt dan mee als studieschuld. Klanten zijn zich daar niet altijd van bewust. Vraag het actuele DUO-overzicht op in plaats van uit te gaan van de opgave van de klant.`,tags:['prestatiebeurs','studieschuld','DUO'],bron:'DUO'},
 {id:'kvx-067',thema:'krediet-vermogen',vraag:'Telt een levenlanglerenkrediet mee in de toetsing?',antwoord:`Een levenlanglerenkrediet is een lening bij DUO voor een opleiding. Het is een schuld met terugbetaalverplichting, net als een studieschuld. Neem het daarom mee in de inventarisatie. Controleer hoe de geldverstrekker deze lening in de toetsing meeneemt.`,tags:['levenlanglerenkrediet','DUO','toetsing'],bron:'DUO'},
 {id:'kvx-068',thema:'krediet-vermogen',vraag:'Hoe ga ik om met een collegegeldkrediet?',antwoord:`Een collegegeldkrediet maakt deel uit van de totale studieschuld bij DUO. Het staat dus in hetzelfde overzicht. Tel het mee bij de totale studieschuld. Controleer of het overzicht van DUO actueel is.`,tags:['collegegeldkrediet','studieschuld','DUO'],bron:'DUO'},
 {id:'kvx-069',thema:'krediet-vermogen',vraag:'Wat als de klant zijn studieschuld niet weet?',antwoord:`Vraag de klant in te loggen bij Mijn DUO en het overzicht te downloaden. Dat geeft de oorspronkelijke schuld, de actuele stand en het maandbedrag. Ga niet uit van een schatting. Bewaar het overzicht in het dossier.`,tags:['studieschuld','DUO','documentatie'],bron:'DUO'},
 {id:'kvx-070',thema:'krediet-vermogen',vraag:'Welke studieschuld telt bij een gezamenlijke aanvraag?',antwoord:`Bij een gezamenlijke aanvraag tellen de studieschulden van beide aanvragers mee. Elke schuld wordt apart beoordeeld volgens de regeling. Vraag van beide aanvragers een DUO-overzicht op. Vergeet ook de schuld van een partner die nog studeert niet.`,tags:['studieschuld','partner','gezamenlijke aanvraag'],bron:''},
 {id:'kvx-071',thema:'krediet-vermogen',vraag:'Hoe ga ik om met een partner die nog studeert en leent bij DUO?',antwoord:`De schuld groeit dan nog, terwijl er nog geen terugbetaling loopt. Voor de toetsing is de actuele stand van belang. Bespreek ook wat de verwachte schuld aan het einde van de studie is. Dat beïnvloedt de betaalbaarheid in de toekomst.`,tags:['studerende partner','studieschuld','toekomst'],bron:''},
 {id:'kvx-072',thema:'krediet-vermogen',vraag:'Wat is een veelgemaakte fout bij het opvragen van studieschuldgegevens?',antwoord:`Een veelgemaakte fout is dat alleen het maandbedrag wordt opgevraagd. Voor de toetsing kan ook de oorspronkelijke of actuele schuld relevant zijn. Een andere fout is een verouderd overzicht. Vraag een recent en volledig overzicht op.`,tags:['fouten','studieschuld','documentatie'],bron:''},
 {id:'kvx-073',thema:'krediet-vermogen',vraag:'Heeft een studieschuld invloed op toeslagen?',antwoord:`Een studieschuld is een schuld in box 3. Voor de vermogenstoets van toeslagen telt het vermogen volgens box 3. De schuld kan het vermogen dus beïnvloeden, maar alleen boven de schuldendrempel. Controleer het actuele bedrag bij de Belastingdienst.`,tags:['studieschuld','toeslagen','box 3'],bron:'Dienst Toeslagen'},
 {id:'kvx-074',thema:'krediet-vermogen',vraag:'Kan een studieschuld worden overgenomen door ouders?',antwoord:`Ouders kunnen geld schenken waarmee de klant zijn studieschuld aflost. De schuld zelf blijft van de klant. Een schenking kan schenkbelasting tot gevolg hebben. Leg vast hoe de aflossing is gefinancierd.`,tags:['studieschuld','schenking','ouders'],bron:''},
 {id:'kvx-075',thema:'krediet-vermogen',vraag:'Wat is het effect van een studieschuld bij een klant die naar het buitenland vertrekt?',antwoord:`De terugbetaalplicht blijft bestaan na emigratie. DUO kan de klant vragen om inkomensgegevens aan te leveren. Zonder die gegevens kan DUO een hoger maandbedrag vaststellen. Wijs de klant op deze verplichting.`,tags:['emigratie','studieschuld','DUO'],bron:'DUO'},
 {id:'kvx-076',thema:'krediet-vermogen',vraag:'Hoe leg ik de studieschuld vast in het adviesrapport?',antwoord:`Neem op:
- hoogte van de schuld en het regime
- actueel maandbedrag en eventuele aflosvrije periodes
- de wijze waarop de schuld in de toetsing is meegenomen
- de bron en datum van het overzicht
Zo is later te reconstrueren hoe de berekening tot stand kwam.`,tags:['adviesrapport','studieschuld','dossier'],bron:''},
 {id:'kvx-077',thema:'krediet-vermogen',vraag:'Waarom kan het maandbedrag van DUO afwijken van de toetsingslast?',antwoord:`Het maandbedrag van DUO volgt uit het regime en eventuele draagkracht. De toetsingslast volgt uit de methode in de regeling voor hypothecair krediet. Die twee hoeven niet gelijk te zijn. Leg dit uit aan de klant om verwarring te voorkomen.`,tags:['maandbedrag','toetsingslast','uitleg'],bron:'Tijdelijke regeling hypothecair krediet'},
 {id:'kvx-078',thema:'krediet-vermogen',vraag:'Hoe bespreek ik een studieschuld met een starter die liever niet aflost?',antwoord:`Leg de gevolgen voor de leencapaciteit en de lange termijn uit. Laat zien wat aflossen en niet aflossen betekent. Benadruk dat de keuze bij de klant ligt. Leg de afweging en de keuze vast.`,tags:['starter','studieschuld','afweging'],bron:''},
 {id:'kvx-079',thema:'krediet-vermogen',vraag:'Is een studieschuld een probleem voor NHG?',antwoord:`Een studieschuld is geen uitsluiting voor NHG. De schuld telt wel mee in de toetsing. NHG volgt de geldende leennormen. Controleer de actuele voorwaarden van NHG.`,tags:['NHG','studieschuld','toetsing'],bron:'NHG'},
 {id:'kvx-080',thema:'krediet-vermogen',vraag:'Moet een klant een studieschuld van het buitenland melden?',antwoord:`Ja, een studielening uit het buitenland is ook een financiële verplichting. Zo een lening staat niet bij DUO en meestal niet in het CKI. Vraag er actief naar bij klanten die in het buitenland hebben gestudeerd. Vraag stukken op waaruit maandlast en restschuld blijken.`,tags:['buitenland','studieschuld','inventarisatie'],bron:''},
 {id:'kvx-081',thema:'krediet-vermogen',vraag:'Wat is het effect van een hogere studieschuld op de betaalbaarheid na pensionering?',antwoord:`Bij een terugbetaaltermijn van 35 jaar kan de schuld tot laat in de loopbaan doorlopen. Dat kan samenvallen met andere lasten of een daling van inkomen. Bespreek dit bij oudere starters. Neem het mee in de lange termijnanalyse.`,tags:['studieschuld','lange termijn','pensioen'],bron:''},
 {id:'kvx-082',thema:'krediet-vermogen',vraag:'Hoe beoordeel ik een klant die bij DUO een achterstand heeft?',antwoord:`Een achterstand bij DUO staat meestal niet in het CKI. Het is wel een signaal over de betaalsituatie. Vraag de klant naar de reden en de stand van zaken. Leg de uitkomst vast in het dossier.`,tags:['DUO','achterstand','signaal'],bron:''},
 {id:'kvx-083',thema:'krediet-vermogen',vraag:'Kan een studieschuld worden meegefinancierd in de hypotheek?',antwoord:`Een geldverstrekker kan toestaan dat de studieschuld wordt afgelost uit de hypotheek. Dat deel is geen eigenwoningschuld en de rente is niet aftrekbaar. De klant ruilt een lage rente vaak in voor een hogere rente. Zet de gevolgen op een rij en leg deze vast.`,tags:['studieschuld','hypotheek','oversluiten'],bron:'Wet IB 2001'},
 {id:'kvx-084',thema:'krediet-vermogen',vraag:'Hoe ga ik om met een studieschuld bij een tweede aanvraag binnen korte tijd?',antwoord:`Vraag opnieuw een actueel DUO-overzicht op. Het maandbedrag of de schuld kan zijn veranderd. Gebruik geen gegevens van een eerdere aanvraag. Leg de nieuwe gegevens vast.`,tags:['actualiteit','studieschuld','documentatie'],bron:''},
 {id:'kvx-085',thema:'krediet-vermogen',vraag:'Wat is het belang van de herkomst van vermogen bij eigen inbreng?',antwoord:`Geldverstrekkers en notarissen moeten onderzoeken waar het geld vandaan komt. Bij een grote eigen inbreng vragen zij om bewijs van de herkomst. Denk aan bankafschriften, schenkingsovereenkomsten of verkoopnota’s. Vraag deze stukken vroeg op om vertraging te voorkomen.`,tags:['herkomst','eigen middelen','Wwft'],bron:'Wwft'},
 {id:'kvx-086',thema:'krediet-vermogen',vraag:'Hoe ga ik om met cryptovaluta als eigen middelen?',antwoord:`Geldverstrekkers stellen vaak extra eisen aan de herkomst van geld uit crypto. Het geld moet meestal eerst naar een Nederlandse bankrekening. Vraag stukken op die de aankoop, verkoop en overboeking laten zien. Controleer de voorwaarden van de geldverstrekker.`,tags:['crypto','eigen middelen','herkomst'],bron:'Wwft'},
 {id:'kvx-087',thema:'krediet-vermogen',vraag:'Wat is het risico van beleggingen als eigen middelen?',antwoord:`Beleggingen kunnen dalen in waarde voordat ze worden verkocht. Daardoor kan er bij passeren minder geld beschikbaar zijn. Bespreek of de klant tijdig wil verkopen. Leg de afspraak en de risicobespreking vast.`,tags:['beleggingen','eigen middelen','risico'],bron:''},
 {id:'kvx-088',thema:'krediet-vermogen',vraag:'Kan geld uit een lijfrenterekening worden gebruikt als eigen inbreng?',antwoord:`Geld op een lijfrenterekening is bestemd voor een lijfrente-uitkering. Vervroegd opnemen leidt in de regel tot belastingheffing en mogelijk revisierente. Het is daarom zelden een geschikte bron voor eigen inbreng. Verwijs de klant voor de exacte gevolgen naar de voorwaarden en de Belastingdienst.`,tags:['lijfrente','eigen middelen','fiscaal'],bron:'Wet IB 2001'},
 {id:'kvx-089',thema:'krediet-vermogen',vraag:'Hoe beoordeel ik spaargeld op naam van een kind?',antwoord:`Geld op een rekening van een minderjarig kind is van het kind. Ouders mogen dat geld niet zomaar voor hun eigen woning gebruiken. Het telt dus niet als eigen middelen van de ouders. Leg dit uit als de klant het wel wil gebruiken.`,tags:['kinderrekening','eigen middelen','eigendom'],bron:'BW'},
 {id:'kvx-090',thema:'krediet-vermogen',vraag:'Wat is een veelgemaakte fout bij het bepalen van eigen middelen?',antwoord:`Een veelgemaakte fout is geen rekening houden met de kosten koper en een buffer. Ook wordt soms geld meegeteld dat al voor iets anders is bestemd. Maak een volledig overzicht van beschikbare middelen en uitgaven. Leg dit vast in het dossier.`,tags:['eigen middelen','fouten','overzicht'],bron:''},
 {id:'kvx-091',thema:'krediet-vermogen',vraag:'Hoe ga ik om met vermogen in een eigen bv als eigen middelen?',antwoord:`Geld in een bv is van de bv, niet van de klant. Om het privé te gebruiken is bijvoorbeeld een dividenduitkering of lening nodig. Dat kan fiscale gevolgen hebben. Verwijs voor de uitwerking naar de fiscalist van de klant.`,tags:['bv','eigen middelen','dividend'],bron:''},
 {id:'kvx-092',thema:'krediet-vermogen',vraag:'Wat is een lening van de eigen bv voor de woning?',antwoord:`Een klant kan geld lenen van zijn eigen bv voor de woning. Onder voorwaarden kan dit eigenwoningschuld zijn. Er gelden zakelijke eisen en de informatieplicht. Verwijs voor de uitwerking naar de fiscalist en leg dit vast.`,tags:['bv','lening','eigenwoningschuld'],bron:'Wet IB 2001'},
 {id:'kvx-093',thema:'krediet-vermogen',vraag:'Hoe ga ik om met een gezamenlijk spaartegoed bij ongehuwde partners?',antwoord:`Bij ongehuwde partners is niet altijd duidelijk van wie het spaargeld is. Dat is relevant bij ongelijke inbreng in de woning. Bespreek of zij afspraken willen vastleggen, bijvoorbeeld in een samenlevingscontract. Leg het gesprek vast.`,tags:['samenwonen','spaargeld','inbreng'],bron:''},
 {id:'kvx-094',thema:'krediet-vermogen',vraag:'Waarom is ongelijke inbreng een vermogensvraagstuk?',antwoord:`Bij ongelijke inbreng brengt een partner meer eigen geld in dan de ander. Zonder afspraken kan dat bij een scheiding of overlijden tot onduidelijkheid leiden. Adviseer de klanten om dit vast te leggen bij de notaris. Leg vast dat u dit heeft besproken.`,tags:['ongelijke inbreng','partners','notaris'],bron:''},
 {id:'kvx-095',thema:'krediet-vermogen',vraag:'Wat bewijst een bankafschrift voor eigen middelen?',antwoord:`Een bankafschrift laat zien dat geld op een bepaald moment beschikbaar is. Het zegt niet altijd iets over de herkomst. Vraag bij grote stortingen ook naar de bron. Controleer de eisen van de geldverstrekker voor de datum van het afschrift.`,tags:['bankafschrift','eigen middelen','bewijs'],bron:''},
 {id:'kvx-096',thema:'krediet-vermogen',vraag:'Hoe ga ik om met contant geld als eigen inbreng?',antwoord:`Contant geld is lastig te onderbouwen. Geldverstrekkers en notarissen zijn hier terughoudend in vanwege de Wwft. Het geld moet in de regel via een bankrekening lopen met een aantoonbare herkomst. Wijs de klant hier vroeg op.`,tags:['contant geld','Wwft','eigen inbreng'],bron:'Wwft'},
 {id:'kvx-097',thema:'krediet-vermogen',vraag:'Telt vakantiegeld of een bonus als eigen middelen?',antwoord:`Vakantiegeld of een bonus kan als eigen middel dienen zodra het is uitbetaald. Voor de aanvraag is aantoonbaar beschikbaar geld leidend. Een verwachte uitbetaling is nog niet zeker. Leg vast welke middelen zijn meegeteld.`,tags:['vakantiegeld','bonus','eigen middelen'],bron:''},
 {id:'kvx-098',thema:'krediet-vermogen',vraag:'Hoe bepaal ik welke buffer een klant na aankoop moet aanhouden?',antwoord:`Er is geen vaste wettelijke norm voor de buffer na aankoop. Het Nibud geeft richtlijnen voor een buffer op basis van huishoudsituatie. Bespreek met de klant welke onvoorziene uitgaven hij verwacht. Leg de afgesproken buffer vast.`,tags:['buffer','Nibud','afspraken'],bron:'Nibud'},
 {id:'kvx-099',thema:'krediet-vermogen',vraag:'Hoe beoordeel ik een klant die een erfenis verwacht?',antwoord:`Een verwachte erfenis is geen zeker vermogen. Het telt daarom niet mee als eigen middel. Bespreek ook de onzekerheid over het moment en de hoogte. Leg vast dat hier niet op is gerekend.`,tags:['verwachte erfenis','eigen middelen','onzekerheid'],bron:''},
 {id:'kvx-100',thema:'krediet-vermogen',vraag:'Hoe ga ik om met een geldlening die de klant aan een ander heeft verstrekt?',antwoord:`Een vordering op een ander is vermogen van de klant. Of het geld beschikbaar is als eigen middel, hangt af van de terugbetaling. Vraag de leningsovereenkomst en bewijs van terugbetaling op. Een vordering die nog openstaat telt niet als beschikbaar geld.`,tags:['vordering','eigen middelen','lening'],bron:''},
 {id:'kvx-101',thema:'krediet-vermogen',vraag:'Wat is de peildatum voor box 3?',antwoord:`Voor box 3 geldt de stand van bezittingen en schulden op 1 januari. Wijzigingen later in het jaar tellen pas mee in het volgende jaar. Dat is relevant bij een aankoop, schenking of aflossing rond de jaarwisseling. Leg bij advies vast welke peildatum geldt.`,tags:['box 3','peildatum','vermogen'],bron:'Belastingdienst'},
 {id:'kvx-102',thema:'krediet-vermogen',vraag:'Waarom maakt de timing van een aflossing rond de jaarwisseling verschil voor box 3?',antwoord:`Box 3 kijkt naar de stand op 1 januari. Een aflossing met spaargeld vlak voor 1 januari verlaagt de box 3-grondslag van het volgende jaar. Een aflossing net erna telt pas een jaar later. Wijs de klant op dit effect, zonder dat het de enige reden voor de keuze wordt.`,tags:['box 3','peildatum','aflossen'],bron:'Belastingdienst'},
 {id:'kvx-103',thema:'krediet-vermogen',vraag:'Hoe werkt de schuldendrempel in box 3?',antwoord:`Schulden in box 3 verlagen de grondslag alleen voor zover ze boven een drempel uitkomen. Fiscale partners hebben samen een hogere drempel. Het drempelbedrag wijzigt en staat op de site van de Belastingdienst. Neem de drempel mee in een rekenvoorbeeld voor de klant.`,tags:['box 3','schulden','drempel'],bron:'Belastingdienst'},
 {id:'kvx-104',thema:'krediet-vermogen',vraag:'Welke schulden vallen in box 3?',antwoord:`Voorbeelden van schulden in box 3 zijn:
- consumptief krediet
- studieschuld
- een hypotheek op een tweede woning
- een lening voor de eigen woning die geen eigenwoningschuld is
De eigenwoningschuld zelf valt in box 1.`,tags:['box 3','schulden','voorbeelden'],bron:'Wet IB 2001'},
 {id:'kvx-105',thema:'krediet-vermogen',vraag:'Hoe verdelen fiscale partners de box 3-grondslag?',antwoord:`Fiscale partners mogen de gezamenlijke grondslag in box 3 onderling vrij verdelen. Dat kan van belang zijn voor heffingskortingen of andere inkomensafhankelijke regelingen. De verdeling gebeurt in de aangifte. Verwijs voor de optimale verdeling naar de belastingadviseur of aangiftesoftware.`,tags:['box 3','fiscaal partner','verdeling'],bron:'Belastingdienst'},
 {id:'kvx-106',thema:'krediet-vermogen',vraag:'Valt een tweede woning in box 3?',antwoord:`Ja, een woning die niet de hoofdverblijfplaats is valt in box 3. Denk aan een vakantiewoning of een verhuurde woning. De waardering gebeurt op basis van de WOZ-waarde, met aparte regels voor verhuurde woningen. Een hypotheek op die woning is een box 3-schuld.`,tags:['box 3','tweede woning','WOZ'],bron:'Wet IB 2001'},
 {id:'kvx-107',thema:'krediet-vermogen',vraag:'Hoe wordt een verhuurde woning in box 3 gewaardeerd?',antwoord:`Voor een verhuurde woning met huurbescherming geldt een lagere waardering via de leegwaarderatio. De ratio hangt af van de huur ten opzichte van de WOZ-waarde. De percentages kunnen per jaar wijzigen. Controleer de actuele tabel bij de Belastingdienst.`,tags:['verhuur','leegwaarderatio','box 3'],bron:'Belastingdienst'},
 {id:'kvx-108',thema:'krediet-vermogen',vraag:'Wat gebeurt er in box 3 als de oude woning na verhuizing niet direct verkocht is?',antwoord:`De oude woning kan tot drie jaar fiscaal als eigen woning blijven gelden. Voorwaarde is dat de woning leeg staat en te koop staat. Wordt de woning verhuurd, dan gaat die regeling niet op en valt de woning in box 3. Bespreek dit met klanten die tijdelijk willen verhuren.`,tags:['oude woning','box 3','verhuur'],bron:'Wet IB 2001'},
 {id:'kvx-109',thema:'krediet-vermogen',vraag:'Hoe werkt box 3 bij een geërfde woning?',antwoord:`Een geërfde woning die niet de hoofdverblijfplaats van de erfgenaam is, valt in box 3. Bij meerdere erfgenamen telt ieders aandeel. De waardering volgt de regels voor box 3. Wijs klanten erop dat dit invloed kan hebben op toeslagen.`,tags:['geërfde woning','box 3','toeslagen'],bron:'Wet IB 2001'},
 {id:'kvx-110',thema:'krediet-vermogen',vraag:'Wat is het verschil tussen een vordering en een schuld bij een familielening in box 3?',antwoord:`Voor de geldgever is een familielening een vordering in box 3. Voor de geldnemer is het een eigenwoningschuld als aan de voorwaarden wordt voldaan. Anders is het voor de geldnemer een box 3-schuld. Leg de kwalificatie vast en wijs op de informatieplicht.`,tags:['familielening','box 3','vordering'],bron:'Wet IB 2001'},
 {id:'kvx-111',thema:'krediet-vermogen',vraag:'Zijn groene beleggingen vrijgesteld in box 3?',antwoord:`Er geldt een vrijstelling voor groene beleggingen tot een bepaald bedrag. Dat bedrag kan wijzigen. Controleer of een fonds of rekening als groene belegging is aangewezen. Raadpleeg de actuele regels bij de Belastingdienst.`,tags:['groene beleggingen','vrijstelling','box 3'],bron:'Belastingdienst'},
 {id:'kvx-112',thema:'krediet-vermogen',vraag:'Wat is de tegenbewijsregeling in box 3?',antwoord:`Met de tegenbewijsregeling kan een belastingplichtige aantonen dat zijn werkelijke rendement lager is dan het forfaitaire rendement. Dan wordt het werkelijke rendement belast. Dit vraagt een eigen berekening en onderbouwing. Verwijs voor de uitwerking naar de Belastingdienst of een fiscalist.`,tags:['tegenbewijs','box 3','werkelijk rendement'],bron:'Belastingdienst'},
 {id:'kvx-113',thema:'krediet-vermogen',vraag:'Wat moet ik als adviseur weten over het werkelijk rendement in box 3?',antwoord:`Er is wetgeving in voorbereiding om box 3 te baseren op werkelijk rendement. De invoering en de details kunnen nog veranderen. Ga in uw advies niet uit van een definitief stelsel. Wijs op de onzekerheid en leg vast dat u dit heeft besproken.`,tags:['werkelijk rendement','box 3','wetgeving'],bron:'Ministerie van Financiën'},
 {id:'kvx-114',thema:'krediet-vermogen',vraag:'Hoe leg ik de box 3-gevolgen vast bij een advies over aflossen?',antwoord:`Neem op welke middelen worden ingezet en wat het effect is op de box 3-grondslag. Vermeld dat de gevolgen afhangen van de actuele tarieven en vrijstellingen. Benoem ook het effect op de buffer. Verwijs naar de fiscalist als de situatie complex is.`,tags:['box 3','aflossen','dossier'],bron:''},
 {id:'kvx-115',thema:'krediet-vermogen',vraag:'Valt de inboedel in box 3?',antwoord:`Nee, de inboedel van de eigen woning valt in de regel niet in box 3. Uitzonderingen gelden voor voorwerpen die als belegging worden aangehouden. Kunst of verzamelingen als belegging kunnen dus wel meetellen. Verwijs bij twijfel naar de Belastingdienst.`,tags:['inboedel','box 3','belegging'],bron:'Wet IB 2001'},
 {id:'kvx-116',thema:'krediet-vermogen',vraag:'Valt een auto in box 3?',antwoord:`Een auto voor eigen gebruik valt in de regel niet in box 3. Een auto die vooral als belegging wordt gehouden kan wel meetellen. Dat is uitzonderlijk. Leg bij twijfel de feiten vast en verwijs door.`,tags:['auto','box 3','vrijstelling'],bron:'Wet IB 2001'},
 {id:'kvx-117',thema:'krediet-vermogen',vraag:'Valt een kapitaalverzekering eigen woning in box 3?',antwoord:`Een kapitaalverzekering eigen woning die aan de voorwaarden van het overgangsrecht voldoet, valt in box 1 en is onder voorwaarden vrijgesteld. Wordt niet meer aan de voorwaarden voldaan, dan kan de waarde naar box 3 gaan. Dat heeft gevolgen voor de vrijstelling. Controleer de polisvoorwaarden en de fiscale status.`,tags:['KEW','box 1','box 3','overgangsrecht'],bron:'Wet IB 2001'},
 {id:'kvx-118',thema:'krediet-vermogen',vraag:'Hoe ga ik om met een lening voor een tweede woning in box 3?',antwoord:`De lening voor een tweede woning is een box 3-schuld. De rente is niet aftrekbaar in box 1. Neem de last mee in de betaalbaarheidstoets. Controleer de voorwaarden van de geldverstrekker voor een tweede woning.`,tags:['tweede woning','box 3','lening'],bron:'Wet IB 2001'},
 {id:'kvx-119',thema:'krediet-vermogen',vraag:'Wat is het effect van een schenking op de box 3-grondslag?',antwoord:`Een ontvangen schenking telt op 1 januari mee als vermogen in box 3, als het geld dan nog aanwezig is. Wordt het geld voor 1 januari in de eigen woning gestoken, dan telt het niet mee in box 3. Ditzelfde geldt voor aflossing van een eigenwoningschuld. Bespreek de timing met de klant.`,tags:['schenking','box 3','peildatum'],bron:'Belastingdienst'},
 {id:'kvx-120',thema:'krediet-vermogen',vraag:'Is er sprake van box 3-heffing over een bankspaarrekening eigen woning?',antwoord:`Een spaarrekening eigen woning die aan het overgangsrecht voldoet, valt onder voorwaarden in box 1. Wordt niet meer aan de voorwaarden voldaan, dan kan het tegoed naar box 3 gaan. Controleer de voorwaarden van de bank en de fiscale status. Leg uw controle vast.`,tags:['spaarrekening eigen woning','overgangsrecht','box 3'],bron:'Wet IB 2001'},
 {id:'kvx-121',thema:'krediet-vermogen',vraag:'Hoe beïnvloedt box 3 de keuze tussen sparen en aflossen?',antwoord:`Spaargeld en beleggingen kunnen box 3-belasting opleveren. Aflossen op de eigenwoningschuld verlaagt het vermogen in box 3, maar ook de aftrekbare rente in box 1. Het netto-effect hangt af van rente, tarieven en de persoonlijke situatie. Maak een berekening en leg die vast.`,tags:['sparen','aflossen','box 3'],bron:''},
 {id:'kvx-122',thema:'krediet-vermogen',vraag:'Hoe ga ik om met een rekening courant met eigen bv in box 3?',antwoord:`Een vordering op of schuld aan de eigen bv kan in box 3 vallen. Voor schulden aan de eigen bv gelden aanvullende regels. Dit is specialistisch terrein. Verwijs naar de fiscalist van de klant.`,tags:['rekening courant','bv','box 3'],bron:'Wet IB 2001'},
 {id:'kvx-123',thema:'krediet-vermogen',vraag:'Wat is een veelgemaakte fout bij box 3 in een adviesgesprek?',antwoord:`Een veelgemaakte fout is werken met verouderde tarieven of vrijstellingen. Een andere fout is vergeten dat de peildatum 1 januari is. Ook wordt soms vergeten dat de partner meetelt. Controleer actuele gegevens bij de Belastingdienst.`,tags:['box 3','fouten','actualiteit'],bron:'Belastingdienst'},
 {id:'kvx-124',thema:'krediet-vermogen',vraag:'Valt het tegoed op een betaalrekening ook in box 3?',antwoord:`Ja, ook het saldo op een betaalrekening telt mee in box 3. Het gaat om de stand op 1 januari. Kleine bedragen vallen vaak binnen het heffingsvrije vermogen. Gebruik de actuele bedragen van de Belastingdienst.`,tags:['betaalrekening','box 3','peildatum'],bron:'Belastingdienst'},
 {id:'kvx-125',thema:'krediet-vermogen',vraag:'Hoe gaat box 3 om met een vordering uit een nalatenschap?',antwoord:`Een vordering van een kind op de langstlevende ouder uit een nalatenschap kan in box 3 vallen. Voor de langstlevende is het dan een schuld. Bij een onderbedeling volgens de wettelijke verdeling gelden specifieke regels. Verwijs naar de notaris of fiscalist.`,tags:['nalatenschap','vordering','box 3'],bron:'Wet IB 2001'},
 {id:'kvx-126',thema:'krediet-vermogen',vraag:'Wat gebeurt er in box 3 met een vruchtgebruik?',antwoord:`Bij vruchtgebruik is de waarde in box 3 in de regel toegerekend aan de vruchtgebruiker. Er gelden specifieke regels en uitzonderingen. Dat is relevant bij nalatenschappen met een woning. Verwijs voor de uitwerking naar de notaris of fiscalist.`,tags:['vruchtgebruik','box 3','nalatenschap'],bron:'Wet IB 2001'},
 {id:'kvx-127',thema:'krediet-vermogen',vraag:'Hoe ga ik om met beleggingen van minderjarige kinderen in box 3?',antwoord:`Vermogen van een minderjarig kind wordt in de regel bij de ouder met gezag aangegeven. Het blijft wel eigendom van het kind. Bij toeslagen telt het vermogen dus mogelijk mee bij de ouder. Verwijs bij twijfel naar de Belastingdienst.`,tags:['kind','box 3','toerekening'],bron:'Wet IB 2001'},
 {id:'kvx-128',thema:'krediet-vermogen',vraag:'Telt een tegoed bij een buitenlandse bank mee in box 3?',antwoord:`Ja, ook buitenlands vermogen telt in principe mee in box 3. Er kunnen regels ter voorkoming van dubbele belasting gelden. Vraag klanten actief naar buitenlands vermogen. Verwijs voor de aangifte naar de fiscalist.`,tags:['buitenland','box 3','vermogen'],bron:'Belastingdienst'},
 {id:'kvx-129',thema:'krediet-vermogen',vraag:'Hoe ga ik om met de waardering van crypto in box 3?',antwoord:`Crypto valt als bezitting in box 3. De waarde op 1 januari is bepalend. Door koersschommelingen kan die sterk afwijken van de huidige waarde. Wijs klanten op hun aangifteplicht.`,tags:['crypto','box 3','waardering'],bron:'Belastingdienst'},
 {id:'kvx-130',thema:'krediet-vermogen',vraag:'Waarom is de afronding van box 3 relevant voor de hypotheekadviseur?',antwoord:`Box 3 bepaalt mede de netto-uitkomst van sparen, beleggen en aflossen. Het speelt een rol bij toeslagen en eigen middelen. De adviseur hoeft geen belastingaangifte te doen, maar moet de samenhang wel kennen. Verwijs voor de details naar de fiscalist.`,tags:['box 3','adviseur','samenhang'],bron:''},
 {id:'kvx-131',thema:'krediet-vermogen',vraag:'Welke toeslagen hebben een vermogenstoets?',antwoord:`Huurtoeslag, zorgtoeslag en kindgebonden budget kennen een vermogenstoets. Kinderopvangtoeslag heeft geen vermogenstoets. De vermogensgrenzen kunnen per jaar wijzigen. Controleer de actuele grenzen bij Dienst Toeslagen.`,tags:['toeslagen','vermogenstoets','Dienst Toeslagen'],bron:'Dienst Toeslagen'},
 {id:'kvx-132',thema:'krediet-vermogen',vraag:'Welk vermogen telt voor de vermogenstoets van toeslagen?',antwoord:`Voor de toeslagen telt het vermogen zoals dat in box 3 wordt vastgesteld. Het gaat om de stand op 1 januari van het toeslagjaar. Ook het vermogen van de toeslagpartner telt mee. De eigen woning valt erbuiten.`,tags:['vermogenstoets','box 3','toeslagpartner'],bron:'Dienst Toeslagen'},
 {id:'kvx-133',thema:'krediet-vermogen',vraag:'Kan een schenking toeslagen beïnvloeden?',antwoord:`Ja, een schenking kan het vermogen op 1 januari verhogen. Daardoor kan de klant boven de vermogensgrens uitkomen. Dat kan het recht op toeslag doen vervallen. Bespreek dit met klanten die een schenking ontvangen en toeslagen hebben.`,tags:['schenking','toeslagen','vermogen'],bron:'Dienst Toeslagen'},
 {id:'kvx-134',thema:'krediet-vermogen',vraag:'Wat is het effect op toeslagen als een klant spaargeld in de woning inbrengt?',antwoord:`Spaargeld dat in de eigen woning wordt gestoken, telt niet meer als box 3-vermogen. Daardoor kan het vermogen onder de grens komen. Dat kan van invloed zijn op het recht op toeslagen. Leg vast dat dit gevolg is besproken, zonder dat het het doel van het advies wordt.`,tags:['spaargeld','eigen woning','toeslagen'],bron:'Dienst Toeslagen'},
 {id:'kvx-135',thema:'krediet-vermogen',vraag:'Wanneer moet een klant een wijziging doorgeven aan Dienst Toeslagen?',antwoord:`Een klant moet wijzigingen in inkomen, vermogen, woonsituatie of partnerschap tijdig doorgeven. Bij een verhuizing naar een koopwoning moet de huurtoeslag worden stopgezet. Te laat doorgeven kan leiden tot terugbetalen. Wijs de klant op deze verplichting.`,tags:['wijziging','Dienst Toeslagen','verhuizing'],bron:'Dienst Toeslagen'},
 {id:'kvx-136',thema:'krediet-vermogen',vraag:'Wat is een toeslagpartner?',antwoord:`Een toeslagpartner is bijvoorbeeld een echtgenoot of een samenwonende met wie de klant aan bepaalde voorwaarden voldoet. Het inkomen en vermogen van de toeslagpartner tellen mee. Bij samenwonen voor een koopwoning kan iemand een toeslagpartner worden. Wijs op de gevolgen voor de toeslagen van beide partners.`,tags:['toeslagpartner','samenwonen','toeslagen'],bron:'Dienst Toeslagen'},
 {id:'kvx-137',thema:'krediet-vermogen',vraag:'Wat gebeurt er met de toeslagen als een klant gaat samenwonen in een nieuwe woning?',antwoord:`Door samenwonen kan een toeslagpartner ontstaan. Inkomen en vermogen worden dan samengeteld. Dat kan leiden tot een lagere of geen toeslag. Bespreek dit bij het opstellen van het maandbudget.`,tags:['samenwonen','toeslagen','maandbudget'],bron:'Dienst Toeslagen'},
 {id:'kvx-138',thema:'krediet-vermogen',vraag:'Hoe neem ik toeslagen mee in een maandbudget na aankoop?',antwoord:`Ga uit van de toeslag die na aankoop nog van toepassing is. Huurtoeslag vervalt bij een koopwoning. Zorgtoeslag en kindgebonden budget kunnen blijven, afhankelijk van inkomen en vermogen. Wees voorzichtig en reken bij twijfel zonder toeslag.`,tags:['maandbudget','toeslagen','aankoop'],bron:''},
 {id:'kvx-139',thema:'krediet-vermogen',vraag:'Wat is het risico als de hypotheekrenteaftrek het toetsingsinkomen verlaagt?',antwoord:`Het toetsingsinkomen voor toeslagen houdt rekening met aftrekposten zoals hypotheekrente. Daardoor kan het toetsingsinkomen dalen na aankoop. Dat kan het recht op toeslag beïnvloeden. Laat de klant de proefberekening van Dienst Toeslagen gebruiken.`,tags:['toetsingsinkomen','hypotheekrenteaftrek','toeslagen'],bron:'Dienst Toeslagen'},
 {id:'kvx-140',thema:'krediet-vermogen',vraag:'Hoe gebruikt een klant de proefberekening van Dienst Toeslagen?',antwoord:`Met de proefberekening op de website van Dienst Toeslagen kan een klant een indicatie krijgen. Hij vult zijn verwachte inkomen, vermogen en situatie in. De uitkomst is niet bindend. Adviseer de klant een kopie te bewaren.`,tags:['proefberekening','Dienst Toeslagen','indicatie'],bron:'Dienst Toeslagen'},
 {id:'kvx-141',thema:'krediet-vermogen',vraag:'Wanneer wordt een toeslag definitief vastgesteld?',antwoord:`Een toeslag wordt definitief vastgesteld nadat het inkomen over het jaar bekend is. Dat gebeurt meestal na de aanslag inkomstenbelasting. Daarna volgt een terugvordering of nabetaling. Wijs de klant op dit verschil tussen voorschot en definitieve toeslag.`,tags:['definitieve vaststelling','toeslag','voorschot'],bron:'Dienst Toeslagen'},
 {id:'kvx-142',thema:'krediet-vermogen',vraag:'Hoe ga ik om met een openstaande terugvordering van toeslagen?',antwoord:`Een terugvordering is een schuld die de klant moet betalen. Vaak loopt er een betalingsregeling. Vraag naar het openstaande bedrag en de maandlast. Neem dit mee in het budget en controleer hoe de geldverstrekker ermee omgaat.`,tags:['terugvordering','toeslagen','schuld'],bron:'Dienst Toeslagen'},
 {id:'kvx-143',thema:'krediet-vermogen',vraag:'Wat moet ik weten over de hersteloperatie toeslagen?',antwoord:`Gedupeerden van de toeslagenaffaire kunnen in een hersteltraject zitten. Dat kan gevolgen hebben voor schulden en vermogen. Wees zorgvuldig en respectvol in het gesprek. Verwijs voor specifieke vragen naar de officiële instanties.`,tags:['hersteloperatie','toeslagen','zorgvuldigheid'],bron:'Dienst Toeslagen'},
 {id:'kvx-144',thema:'krediet-vermogen',vraag:'Telt een compensatie uit het hersteltraject toeslagen mee als vermogen?',antwoord:`Voor compensatiebedragen uit het hersteltraject gelden speciale regels voor vermogen en toeslagen. De details kunnen wijzigen. Controleer de actuele informatie bij de officiële instanties. Leg vast welke bron u heeft gebruikt.`,tags:['compensatie','hersteloperatie','vermogen'],bron:'Dienst Toeslagen'},
 {id:'kvx-145',thema:'krediet-vermogen',vraag:'Heeft een eigen woning invloed op kindgebonden budget?',antwoord:`De eigen woning zelf telt niet mee in de vermogenstoets. Wel kan het inkomen veranderen door hypotheekrenteaftrek. Dat kan doorwerken in het kindgebonden budget. Laat de klant een proefberekening maken.`,tags:['kindgebonden budget','eigen woning','toeslagen'],bron:'Dienst Toeslagen'},
 {id:'kvx-146',thema:'krediet-vermogen',vraag:'Hoe beïnvloedt een huurder-koper situatie de huurtoeslag?',antwoord:`Zodra de klant eigenaar wordt van de woning, heeft hij geen recht meer op huurtoeslag voor die woning. Dit geldt ook als hij eerst huurde en nu koopt. Vraag de klant om de huurtoeslag tijdig stop te zetten. Neem dit mee in het budget.`,tags:['huurtoeslag','kopen','stopzetten'],bron:'Dienst Toeslagen'},
 {id:'kvx-147',thema:'krediet-vermogen',vraag:'Waarom is een toeslag geen stabiel inkomen voor de hypotheek?',antwoord:`Een toeslag is afhankelijk van inkomen, vermogen en gezinssituatie. Die kunnen snel veranderen. Daarom tellen toeslagen in de regel niet mee als toetsingsinkomen. In het maandbudget kunt u er wel rekening mee houden, met voorzichtigheid.`,tags:['toeslag','inkomen','stabiliteit'],bron:''},
 {id:'kvx-148',thema:'krediet-vermogen',vraag:'Wat is het effect van extra aflossen op toeslagen?',antwoord:`Extra aflossen met spaargeld verlaagt het box 3-vermogen. Dat kan het recht op toeslagen vergroten. Tegelijk daalt de hypotheekrenteaftrek, wat het toetsingsinkomen kan verhogen. Laat de klant de netto-effecten doorrekenen.`,tags:['extra aflossen','toeslagen','vermogen'],bron:''},
 {id:'kvx-149',thema:'krediet-vermogen',vraag:'Wat leg ik vast over toeslagen in het advies?',antwoord:`Leg vast welke toeslagen de klant ontvangt en of die na aankoop blijven. Noteer of u toeslagen in het maandbudget heeft meegenomen. Vermeld dat de bedragen een indicatie zijn. Verwijs naar Dienst Toeslagen voor een definitieve berekening.`,tags:['dossier','toeslagen','maandbudget'],bron:''},
 {id:'kvx-150',thema:'krediet-vermogen',vraag:'Hoe ga ik om met een klant die huurtoeslag wil blijven ontvangen na aankoop?',antwoord:`Bij een koopwoning bestaat geen recht op huurtoeslag. Blijft de klant toch huurtoeslag ontvangen, dan wordt die teruggevorderd. Leg dit duidelijk uit. Leg vast dat u dit heeft besproken.`,tags:['huurtoeslag','koopwoning','terugvordering'],bron:'Dienst Toeslagen'},
 {id:'kvx-151',thema:'krediet-vermogen',vraag:'Telt vermogen van een inwonend meerderjarig kind mee voor huurtoeslag?',antwoord:`Bij huurtoeslag kunnen ook medebewoners meetellen. Dat geldt voor inkomen en vermogen, met uitzonderingen. Dit is relevant als een klant van huur naar koop gaat. Controleer de regels bij Dienst Toeslagen.`,tags:['medebewoner','huurtoeslag','vermogen'],bron:'Dienst Toeslagen'},
 {id:'kvx-152',thema:'krediet-vermogen',vraag:'Wie moet de aangifte schenkbelasting doen?',antwoord:`De ontvanger van de schenking doet de aangifte schenkbelasting. Dat geldt ook als hij een vrijstelling wil gebruiken waarvoor een aangifte nodig is. De aangifte moet tijdig na afloop van het jaar van de schenking worden gedaan. Controleer de actuele termijn bij de Belastingdienst.`,tags:['aangifte','schenkbelasting','ontvanger'],bron:'Belastingdienst'},
 {id:'kvx-153',thema:'krediet-vermogen',vraag:'Waarom vraagt een geldverstrekker om een schenkingsverklaring?',antwoord:`De geldverstrekker wil zeker weten dat het geld een schenking is en geen lening. Een lening zou een extra verplichting zijn die de betaalbaarheid raakt. Een verklaring van de schenker legt vast dat er geen terugbetaling wordt verwacht. Gebruik het model van de geldverstrekker als dat er is.`,tags:['schenkingsverklaring','geldverstrekker','eigen middelen'],bron:''},
 {id:'kvx-154',thema:'krediet-vermogen',vraag:'Mag een schenking voorwaarden bevatten als die voor de hypotheek wordt gebruikt?',antwoord:`Geldverstrekkers verlangen meestal dat de schenking onvoorwaardelijk is. Een terugbetaalverplichting maakt het in feite een lening. Een herroepingsclausule kan ook problemen geven. Controleer de voorwaarden van de geldverstrekker en lees de schenkingsakte goed.`,tags:['schenking','voorwaarden','onvoorwaardelijk'],bron:''},
 {id:'kvx-155',thema:'krediet-vermogen',vraag:'Wat is het verschil tussen de jaarlijkse vrijstelling en de eenmalig verhoogde vrijstelling voor kinderen?',antwoord:`Ouders kunnen elk jaar een bedrag belastingvrij aan een kind schenken. Daarnaast bestaat een eenmalig verhoogde vrijstelling voor kinderen in een bepaalde leeftijdscategorie. De verhoogde vrijstelling moet in de aangifte worden geclaimd. Gebruik de actuele bedragen en voorwaarden van de Belastingdienst.`,tags:['vrijstelling','ouder-kind','schenkbelasting'],bron:'Belastingdienst'},
 {id:'kvx-156',thema:'krediet-vermogen',vraag:'Bestaat de eenmalig verhoogde vrijstelling voor de eigen woning nog?',antwoord:`Nee, de verhoogde schenkingsvrijstelling voor de eigen woning is per 1 januari 2024 afgeschaft. De algemene eenmalig verhoogde vrijstelling voor kinderen bestaat nog. Daarvoor hoeft het geld niet in de woning te worden gebruikt. Controleer de actuele voorwaarden bij de Belastingdienst.`,tags:['jubelton','afschaffing','vrijstelling'],bron:'Belastingdienst'},
 {id:'kvx-157',thema:'krediet-vermogen',vraag:'Geldt de vrijstelling voor ouders per ouder of voor beide ouders samen?',antwoord:`De vrijstelling van ouders aan een kind geldt in de regel voor beide ouders samen. Bij gescheiden ouders kunnen andere regels gelden. Verwijs voor de exacte uitwerking naar de Belastingdienst. Leg vast welke schenker welk bedrag heeft geschonken.`,tags:['vrijstelling','ouders','schenker'],bron:'Belastingdienst'},
 {id:'kvx-158',thema:'krediet-vermogen',vraag:'Kunnen grootouders gebruikmaken van de verhoogde vrijstelling voor kinderen?',antwoord:`Nee, de verhoogde vrijstelling geldt alleen voor schenkingen van ouders aan kinderen. Voor schenkingen van grootouders geldt de algemene vrijstelling. Het tarief voor kleinkinderen kan bovendien anders zijn. Gebruik de actuele tabellen van de Belastingdienst.`,tags:['grootouders','kleinkinderen','vrijstelling'],bron:'Belastingdienst'},
 {id:'kvx-159',thema:'krediet-vermogen',vraag:'Wat gebeurt er als de schenker binnen korte tijd na de schenking overlijdt?',antwoord:`Een schenking binnen 180 dagen voor het overlijden wordt in de erfbelasting als verkrijging uit de nalatenschap aangemerkt. Er wordt dan erfbelasting geheven in plaats van schenkbelasting. Betaalde schenkbelasting wordt verrekend. Dit is relevant bij schenkingen door ernstig zieke ouders.`,tags:['180 dagen','schenking','erfbelasting'],bron:'Successiewet 1956'},
 {id:'kvx-160',thema:'krediet-vermogen',vraag:'Hoe bewijst een klant dat een geldbedrag een schenking is en geen lening?',antwoord:`Gebruik een schriftelijke schenkingsovereenkomst of verklaring. Vermeld daarin bedrag, datum, schenker, ontvanger en dat er geen terugbetaling volgt. Bewaar ook het bankafschrift van de overboeking. Bewaar een kopie van de aangifte schenkbelasting als die is gedaan.`,tags:['schenking','bewijs','dossier'],bron:''},
 {id:'kvx-161',thema:'krediet-vermogen',vraag:'Wat is het verschil tussen een schenking op papier en een familielening?',antwoord:`Bij een schenking op papier schenkt de schenker een bedrag maar betaalt het niet uit. De ontvanger heeft een vordering op de schenker. Bij een familielening leent de klant geld van familie en moet hij terugbetalen. De fiscale behandeling is heel verschillend en vraagt notariële begeleiding.`,tags:['schenking op papier','familielening','verschil'],bron:'Successiewet 1956'},
 {id:'kvx-162',thema:'krediet-vermogen',vraag:'Waarom vraagt een schenking op papier om een notariële akte?',antwoord:`Voor de fiscale erkenning van een schenking op papier gelden eisen. Een notariële akte en de jaarlijkse betaling van rente volgens een wettelijk minimum horen daarbij. Zonder die eisen kan de vordering bij overlijden fiscaal als legaat worden behandeld. Verwijs naar de notaris.`,tags:['schenking op papier','notaris','akte'],bron:'Successiewet 1956'},
 {id:'kvx-163',thema:'krediet-vermogen',vraag:'Is kwijtschelding van een familielening een schenking?',antwoord:`Ja, het kwijtschelden van een lening of een deel daarvan is in principe een schenking. Er kan schenkbelasting verschuldigd zijn boven de vrijstelling. De resterende schuld kan ook fiscale gevolgen hebben voor de eigenwoningschuld. Verwijs voor de uitwerking naar de fiscalist en leg dit vast.`,tags:['kwijtschelding','familielening','schenking'],bron:'Successiewet 1956'},
 {id:'kvx-164',thema:'krediet-vermogen',vraag:'Wat is het risico van een renteloze lening van ouders?',antwoord:`Bij een renteloze lening kan het rentevoordeel als schenking worden gezien. Voor de eigenwoningschuld moet rente bovendien zakelijk zijn om aftrekbaar te zijn. Een renteloze lening is fiscaal dus vaak nadelig. Leg de rente en de voorwaarden vast in een overeenkomst.`,tags:['renteloze lening','schenking','rente'],bron:'Wet IB 2001'},
 {id:'kvx-165',thema:'krediet-vermogen',vraag:'Hoe ga ik om met een schenking uit het buitenland?',antwoord:`Of Nederlandse schenkbelasting verschuldigd is, hangt af van de woonplaats van de schenker. Een Nederlander die is geëmigreerd, kan nog tien jaar als inwoner worden aangemerkt. Daarnaast vragen geldverstrekkers extra bewijs van herkomst. Verwijs voor de fiscale gevolgen naar de fiscalist.`,tags:['buitenland','schenking','woonplaats'],bron:'Successiewet 1956'},
 {id:'kvx-166',thema:'krediet-vermogen',vraag:'Valt een schenking binnen het huwelijk in de gemeenschap van goederen?',antwoord:`Voor huwelijken vanaf 1 januari 2018 geldt de beperkte gemeenschap van goederen. Een schenking of erfenis valt dan in de regel buiten de gemeenschap. Bij oudere huwelijken hangt het af van het huwelijksregime en eventuele uitsluitingsclausules. Vraag de klant naar zijn situatie.`,tags:['gemeenschap','huwelijk','schenking'],bron:'BW'},
 {id:'kvx-167',thema:'krediet-vermogen',vraag:'Wat gebeurt er als een geschonken bedrag in een gezamenlijke woning wordt gestoken?',antwoord:`Als een schenking of erfenis buiten de gemeenschap valt, kan de ontvanger een vergoedingsrecht hebben. Dat speelt bij scheiding of overlijden. Leg de inbreng goed vast. Adviseer de klant om dit met de notaris te bespreken.`,tags:['inbreng','vergoedingsrecht','notaris'],bron:'BW'},
 {id:'kvx-168',thema:'krediet-vermogen',vraag:'Wat is een uitsluitingsclausule?',antwoord:`Een uitsluitingsclausule is een bepaling in een testament of schenkingsakte. Daarmee valt de verkrijging buiten een huwelijksgemeenschap. Dat kan de ontvanger beschermen bij scheiding. Vraag bij grote schenkingen of erfenissen naar de akte.`,tags:['uitsluitingsclausule','testament','schenking'],bron:'BW'},
 {id:'kvx-169',thema:'krediet-vermogen',vraag:'Wie doet de aangifte erfbelasting?',antwoord:`De aangifte erfbelasting wordt meestal door de erfgenamen samen gedaan. In de praktijk doet vaak de executeur of de notaris dit. De verschuldigde erfbelasting blijft per verkrijger. De standaardtermijn is acht maanden na overlijden, met de mogelijkheid van uitstel.`,tags:['erfbelasting','aangifte','executeur'],bron:'Successiewet 1956'},
 {id:'kvx-170',thema:'krediet-vermogen',vraag:'Wat zijn de mogelijkheden voor een erfgenaam bij een nalatenschap?',antwoord:`Een erfgenaam kan een nalatenschap zuiver aanvaarden, beneficiair aanvaarden of verwerpen. Bij zuiver aanvaarden is hij ook aansprakelijk voor de schulden. Bij beneficiair aanvaarden is de aansprakelijkheid beperkt tot de nalatenschap. Verwijs bij twijfel naar de notaris.`,tags:['aanvaarden','verwerpen','nalatenschap'],bron:'BW'},
 {id:'kvx-171',thema:'krediet-vermogen',vraag:'Wanneer kan een erfgenaam over het geld uit een erfenis beschikken?',antwoord:`Dat hangt af van de afwikkeling van de nalatenschap. Vaak is een verklaring van erfrecht nodig voordat banken rekeningen vrijgeven. Daarna moet de verdeling worden afgerond. Plan de hypotheekaanvraag niet te krap op de verwachte ontvangst.`,tags:['erfenis','beschikbaarheid','verklaring van erfrecht'],bron:''},
 {id:'kvx-172',thema:'krediet-vermogen',vraag:'Hoe werkt de wettelijke verdeling voor de langstlevende partner?',antwoord:`Bij de wettelijke verdeling krijgt de langstlevende echtgenoot de goederen. De kinderen krijgen een geldvordering op de langstlevende. Die vordering is meestal pas opeisbaar bij overlijden van de langstlevende. Dat is relevant voor de woning en de hypotheek van de langstlevende.`,tags:['wettelijke verdeling','langstlevende','kinderen'],bron:'BW'},
 {id:'kvx-173',thema:'krediet-vermogen',vraag:'Wat betekent de geldvordering van kinderen voor de hypotheek van de langstlevende?',antwoord:`De vordering van de kinderen is een schuld van de langstlevende. Die is meestal niet direct opeisbaar. Geldverstrekkers kunnen er wel naar vragen. Vraag de klant de verklaring van erfrecht en de afwikkeling op.`,tags:['geldvordering','langstlevende','hypotheek'],bron:'BW'},
 {id:'kvx-174',thema:'krediet-vermogen',vraag:'Erft een geregistreerd partner hetzelfde als een echtgenoot?',antwoord:`Een geregistreerd partner staat in het erfrecht in de regel gelijk aan een echtgenoot. Zonder testament geldt dus de wettelijke verdeling. Ook in de erfbelasting geldt een vergelijkbare partnerbehandeling. Controleer de situatie bij de notaris.`,tags:['geregistreerd partnerschap','erfrecht','partner'],bron:'BW'},
 {id:'kvx-175',thema:'krediet-vermogen',vraag:'Wat moet een samenwonend stel regelen voor de woning bij overlijden?',antwoord:`Ongehuwde partners erven zonder testament niet van elkaar. Een samenlevingscontract met verblijvingsbeding en een testament kunnen dit regelen. Voor de erfbelasting gelden aanvullende voorwaarden om als partner te worden behandeld. Adviseer om dit met de notaris te bespreken.`,tags:['samenwonen','testament','verblijvingsbeding'],bron:''},
 {id:'kvx-176',thema:'krediet-vermogen',vraag:'Wat is een verblijvingsbeding?',antwoord:`Een verblijvingsbeding staat in een samenlevingscontract. Bij overlijden komt het aandeel in gezamenlijke bezittingen toe aan de langstlevende. Het kan bij de woning een belangrijke rol spelen. Laat de werking toetsen door de notaris.`,tags:['verblijvingsbeding','samenlevingscontract','woning'],bron:''},
 {id:'kvx-177',thema:'krediet-vermogen',vraag:'Valt een geërfde woning direct in box 3?',antwoord:`Een geërfde woning die niet de hoofdverblijfplaats van de erfgenaam is, valt in box 3. Dat geldt vanaf de verkrijging, ook als de nalatenschap nog niet is verdeeld. Bij leegstand en verkoop kan dit een aanzienlijke last zijn. Bespreek de verkoopplanning met de klant.`,tags:['geërfde woning','box 3','verkoop'],bron:'Wet IB 2001'},
 {id:'kvx-178',thema:'krediet-vermogen',vraag:'Kan een erfgenaam de ouderlijke woning overnemen en financieren?',antwoord:`Een erfgenaam kan de woning overnemen van de andere erfgenamen. Voor het uitkopen van broers of zussen kan een hypotheek nodig zijn. Als de erfgenaam er gaat wonen, kan dat deel onder voorwaarden eigenwoningschuld zijn. Laat de waarde vaststellen met een taxatie.`,tags:['ouderlijke woning','overname','financiering'],bron:''},
 {id:'kvx-179',thema:'krediet-vermogen',vraag:'Hoe ga ik om met een erfenis die bestaat uit een woning met hypotheek?',antwoord:`De hypotheek gaat mee in de nalatenschap. De erfgenamen moeten met de geldverstrekker afspraken maken over aflossing of overname. Bij verkoop wordt de schuld uit de opbrengst afgelost. Vraag de klant de stand van de schuld op.`,tags:['erfenis','hypotheek','woning'],bron:''},
 {id:'kvx-180',thema:'krediet-vermogen',vraag:'Wat is het verschil tussen erfgenaam en legataris?',antwoord:`Een erfgenaam krijgt een deel van de nalatenschap en ook van de schulden. Een legataris krijgt een bepaald goed of bedrag en is niet aansprakelijk voor de schulden. Een legaat wordt via het testament toegekend. Dit is van belang bij het bepalen van eigen middelen.`,tags:['legataris','erfgenaam','testament'],bron:'BW'},
 {id:'kvx-181',thema:'krediet-vermogen',vraag:'Wat is de legitieme portie?',antwoord:`De legitieme portie is het deel van de nalatenschap waarop een kind recht heeft. Het kind kan dit opeisen, ook als het in het testament is onterfd. Het is een geldvordering. Verwijs bij vragen naar de notaris.`,tags:['legitieme portie','kind','erfrecht'],bron:'BW'},
 {id:'kvx-182',thema:'krediet-vermogen',vraag:'Wat moet ik vastleggen als een klant een erfenis als eigen middelen inbrengt?',antwoord:`Leg vast:
- de verklaring van erfrecht of akte van verdeling
- het bankafschrift met de ontvangst
- of er nog erfbelasting moet worden betaald
- welk deel beschikbaar is na kosten
Zo kunt u later aantonen dat de middelen aanwezig waren.`,tags:['erfenis','dossier','eigen middelen'],bron:''},
 {id:'kvx-183',thema:'krediet-vermogen',vraag:'Waarom moet een klant rekening houden met erfbelasting bij een erfenis als eigen inbreng?',antwoord:`Erfbelasting wordt pas na de aangifte en de aanslag betaald. Als de erfenis al volledig in de woning is gestoken, moet het bedrag uit andere middelen komen. Bespreek dit vooraf. Houd een buffer aan voor de verwachte aanslag.`,tags:['erfbelasting','eigen inbreng','buffer'],bron:''},
 {id:'kvx-184',thema:'krediet-vermogen',vraag:'Wat is vruchtgebruik bij een nalatenschap met woning?',antwoord:`Bij vruchtgebruik mag de vruchtgebruiker de woning gebruiken. De blote eigendom ligt bij andere erfgenamen. Dat heeft gevolgen voor de financiering en het onderpand. Controleer de voorwaarden van de geldverstrekker en verwijs naar de notaris.`,tags:['vruchtgebruik','blote eigendom','woning'],bron:'BW'},
 {id:'kvx-185',thema:'krediet-vermogen',vraag:'Hoe ga ik om met een schenking aan een kind dat nog onder bewind staat?',antwoord:`Bij bewind beheert de bewindvoerder het vermogen. Het kind kan dan niet zelfstandig over het geld beschikken. Voor de inbreng in een woning is medewerking van de bewindvoerder nodig. Vraag de beschikking en de voorwaarden van het bewind op.`,tags:['bewind','schenking','inbreng'],bron:'BW'},
 {id:'kvx-186',thema:'krediet-vermogen',vraag:'Wat is testamentair bewind?',antwoord:`Bij testamentair bewind wijst de erflater een bewindvoerder aan die de erfenis beheert. De erfgenaam kan dan niet zelfstandig over het vermogen beschikken. Dit is relevant als een klant een erfenis voor een woning wil gebruiken. Vraag het testament en de bevoegdheden op.`,tags:['testamentair bewind','erfenis','beschikking'],bron:'BW'},
 {id:'kvx-187',thema:'krediet-vermogen',vraag:'Wat is een veelgemaakte fout bij schenkingen voor een hypotheek?',antwoord:`Veelgemaakte fouten zijn:
- de schenking is niet vastgelegd
- het geld komt te laat binnen
- er is geen aangifte gedaan als dat nodig was
- het verschil tussen lening en schenking is onduidelijk
Leg de afspraken vroeg in het traject vast.`,tags:['fouten','schenking','hypotheek'],bron:''},
 {id:'kvx-188',thema:'krediet-vermogen',vraag:'Hoe ga ik om met een schenking die pas na passeren binnenkomt?',antwoord:`Een geldverstrekker wil meestal zien dat de eigen middelen voor passeren beschikbaar zijn. Een latere schenking kan niet worden meegeteld als het geld er bij passeren niet is. Plan de overboeking tijdig. Bespreek de planning met schenker en klant.`,tags:['schenking','timing','passeren'],bron:''},
 {id:'kvx-189',thema:'krediet-vermogen',vraag:'Wat is het effect van een schenking op een bestaande eigenwoningschuld?',antwoord:`Een schenking die wordt gebruikt om de eigenwoningschuld af te lossen, verlaagt die schuld. De rente over het afgeloste deel is daarna niet meer aftrekbaar. Een later nieuwe lening voor de woning kan weer eigenwoningschuld zijn, met de geldende regels. Leg de afweging vast.`,tags:['schenking','aflossen','eigenwoningschuld'],bron:'Wet IB 2001'},
 {id:'kvx-190',thema:'krediet-vermogen',vraag:'Kan een klant een schenking met terugwerkende kracht laten gelden voor een vrijstelling?',antwoord:`Een schenking geldt op het moment dat ze plaatsvindt. Voor vrijstellingen is het jaar van de schenking bepalend. Het is niet mogelijk de schenking achteraf in een ander jaar te plaatsen. Leg de datum van de overboeking vast.`,tags:['schenking','datum','vrijstelling'],bron:'Belastingdienst'},
 {id:'kvx-191',thema:'krediet-vermogen',vraag:'Hoe ga ik om met een woning die door ouders aan een kind wordt verkocht?',antwoord:`Bij een verkoop tussen ouders en kind moet de koopsom zakelijk zijn. Een te lage prijs kan een schenking zijn. Laat de waarde vaststellen met een taxatie. Verwijs naar de notaris en leg de waarde vast.`,tags:['verkoop','ouders','taxatie'],bron:'Successiewet 1956'},
 {id:'kvx-192',thema:'krediet-vermogen',vraag:'Wat als ouders een woning kopen en aan hun kind verhuren?',antwoord:`De woning valt voor de ouders in box 3. Voor de huur gelden de gewone huurregels. De huurprijs moet zakelijk zijn om discussie over schenking te voorkomen. Verwijs voor de fiscale gevolgen naar de fiscalist.`,tags:['ouders','verhuur','box 3'],bron:''},
 {id:'kvx-193',thema:'krediet-vermogen',vraag:'Wat is een schenking onder opschortende voorwaarde?',antwoord:`Bij een schenking onder opschortende voorwaarde gaat de schenking pas in als een gebeurtenis plaatsvindt. Zolang die niet heeft plaatsgevonden, is het geld niet van de ontvanger. Voor de hypotheek telt het dan nog niet als eigen middel. Controleer de voorwaarden van de geldverstrekker.`,tags:['opschortende voorwaarde','schenking','eigen middelen'],bron:'BW'},
 {id:'kvx-194',thema:'krediet-vermogen',vraag:'Hoe ga ik om met een erfenis van een klant die in een schuldtraject zit?',antwoord:`Een erfenis kan in een schuldtraject naar de schuldeisers gaan. Dat hangt af van het traject en de afspraken. De klant moet dit melden bij de schuldhulpverlener of bewindvoerder. Verwijs de klant naar die partij.`,tags:['erfenis','schuldtraject','schuldeisers'],bron:''},
 {id:'kvx-195',thema:'krediet-vermogen',vraag:'Wat moet ik weten over een erfenis uit het buitenland?',antwoord:`Het recht van het land van de overledene kan van toepassing zijn. Ook kan buitenlandse erfbelasting verschuldigd zijn. Er zijn regels ter voorkoming van dubbele heffing. Verwijs naar een notaris of fiscalist met internationale ervaring.`,tags:['buitenland','erfenis','dubbele heffing'],bron:''},
 {id:'kvx-196',thema:'krediet-vermogen',vraag:'Wat is een akte van verdeling?',antwoord:`Een akte van verdeling legt vast hoe de nalatenschap tussen erfgenamen wordt verdeeld. Bij een woning is een notariële akte nodig voor de overdracht. De akte is een belangrijk bewijsstuk voor de geldverstrekker. Vraag deze op als de klant een woning of geld uit de nalatenschap inbrengt.`,tags:['akte van verdeling','nalatenschap','bewijs'],bron:''},
 {id:'kvx-197',thema:'krediet-vermogen',vraag:'Kan een klant een hypotheek krijgen voor een woning die nog in een onverdeelde nalatenschap zit?',antwoord:`Zolang de nalatenschap onverdeeld is, is de woning van alle erfgenamen samen. Financieren is dan lastig. Meestal wordt eerst verdeeld of overgedragen. Controleer de voorwaarden van de geldverstrekker en betrek de notaris.`,tags:['onverdeelde nalatenschap','financiering','notaris'],bron:''},
 {id:'kvx-198',thema:'krediet-vermogen',vraag:'Hoe beïnvloedt een erfenis de toeslagen van de klant?',antwoord:`Een erfenis verhoogt het vermogen op 1 januari, als het geld nog aanwezig is. Dat kan het recht op toeslagen beïnvloeden. Ook een geërfde woning die in box 3 valt telt mee. Wijs de klant op het tijdig doorgeven van wijzigingen.`,tags:['erfenis','toeslagen','vermogen'],bron:'Dienst Toeslagen'},
 {id:'kvx-199',thema:'krediet-vermogen',vraag:'Hoe ga ik om met de wens van ouders om een kind bij de hypotheek te helpen zonder te schenken?',antwoord:`Ouders kunnen bijvoorbeeld geld lenen aan hun kind of borg staan. Elke vorm heeft eigen fiscale en juridische gevolgen. Bespreek de mogelijkheden in algemene zin. Verwijs voor de uitwerking naar de notaris of fiscalist.`,tags:['ouders','hulp','varianten'],bron:''},
 {id:'kvx-200',thema:'krediet-vermogen',vraag:'Wat moet ik weten over schenken aan een stiefkind?',antwoord:`Een stiefkind kan in de schenk- en erfbelasting onder voorwaarden gelijk worden gesteld aan een kind. Dat kan gevolgen hebben voor de vrijstelling en het tarief. Verwijs naar de Belastingdienst of de notaris. Leg vast dat u de situatie heeft gesignaleerd.`,tags:['stiefkind','schenking','vrijstelling'],bron:'Successiewet 1956'},
 {id:'kvx-201',thema:'krediet-vermogen',vraag:'Hoe ga ik om met een schenking aan een klant die het geld gezamenlijk met de partner inbrengt?',antwoord:`Als alleen de klant de schenking ontvangt, is het geld van hem. Wordt het in een gezamenlijke woning gestoken, dan ontstaat mogelijk een vergoedingsrecht of ongelijke inbreng. Adviseer om afspraken vast te leggen. Leg het gesprek vast.`,tags:['schenking','partner','inbreng'],bron:''},
 {id:'kvx-202',thema:'krediet-vermogen',vraag:'Is een erfenis direct beschikbaar als eigen inbreng bij de aankoop?',antwoord:`Niet altijd. Afwikkeling van een nalatenschap kan tijd kosten. Ook kunnen er nog schulden of belastingen worden afgerekend. Reken pas met de erfenis als het geld beschikbaar en aantoonbaar is.`,tags:['erfenis','beschikbaarheid','eigen inbreng'],bron:''},
 {id:'kvx-203',thema:'krediet-vermogen',vraag:'Welke vragen stel ik standaard bij de afweging aflossen of sparen?',antwoord:`Stel in elk geval vragen over:
- de hoogte van de buffer na aflossing
- verwachte grote uitgaven
- de rente op de hypotheek en op spaargeld
- de fiscale positie in box 1 en box 3
- de wens om later flexibel te zijn
Leg de antwoorden vast in het dossier.`,tags:['aflossen','sparen','inventarisatie'],bron:''},
 {id:'kvx-204',thema:'krediet-vermogen',vraag:'Waarom is liquiditeit een belangrijk argument tegen extra aflossen?',antwoord:`Geld dat in de woning zit, is niet direct beschikbaar. Opnieuw lenen kan alleen als de klant daarvoor in aanmerking komt. Bij inkomensdaling of hogere lasten kan dat lastig zijn. Bespreek dit risico expliciet.`,tags:['liquiditeit','aflossen','risico'],bron:''},
 {id:'kvx-205',thema:'krediet-vermogen',vraag:'Wat is het verschil tussen aflossen met lagere maandlast en aflossen met kortere looptijd?',antwoord:`Na extra aflossen kan de geldverstrekker de maandlast verlagen of de looptijd verkorten. De keuze verschilt per geldverstrekker en product. Een lagere maandlast geeft ruimte in het budget. Een kortere looptijd bespaart meestal meer rente.`,tags:['extra aflossen','maandlast','looptijd'],bron:''},
 {id:'kvx-206',thema:'krediet-vermogen',vraag:'Hoe beïnvloedt een lagere risico-opslag de afweging om af te lossen?',antwoord:`Veel geldverstrekkers rekenen een lagere rente bij een lagere schuld ten opzichte van de woningwaarde. Extra aflossen kan de klant in een gunstiger tariefklasse brengen. Dat voordeel geldt dan over de hele schuld. Controleer de voorwaarden van de geldverstrekker over herberekening van de rente.`,tags:['risico-opslag','tariefklasse','aflossen'],bron:''},
 {id:'kvx-207',thema:'krediet-vermogen',vraag:'Hoe werkt een lagere tariefklasse door een hogere woningwaarde?',antwoord:`Een stijging van de woningwaarde kan de verhouding tussen schuld en waarde verbeteren. Sommige geldverstrekkers passen dan de rente aan na een nieuwe taxatie of waardebepaling. Dat gebeurt niet altijd automatisch. Controleer de voorwaarden en de kosten van een taxatie.`,tags:['woningwaarde','tariefklasse','taxatie'],bron:''},
 {id:'kvx-208',thema:'krediet-vermogen',vraag:'Hoe reken ik het effect van extra aflossen door zonder jaarafhankelijke cijfers?',antwoord:`Vergelijk de bruto rentebesparing met het verlies aan renteaftrek. Zet daar het eventuele box 3-voordeel tegenover. Gebruik de actuele tarieven en de rente van de klant. Presenteer het als een indicatie en leg de uitgangspunten vast.`,tags:['rekenvoorbeeld','aflossen','netto-effect'],bron:''},
 {id:'kvx-209',thema:'krediet-vermogen',vraag:'Wat is het effect van de Wet Hillen op extra aflossen?',antwoord:`De Wet Hillen wordt vanaf 2019 in 30 jaar afgebouwd. Klanten met een lage of geen eigenwoningschuld hebben daardoor geleidelijk minder voordeel. Dat maakt volledig aflossen fiscaal minder gunstig dan vroeger. Bespreek dit met klanten die bijna schuldenvrij zijn.`,tags:['Wet Hillen','aflossen','afbouw'],bron:'Wet IB 2001'},
 {id:'kvx-210',thema:'krediet-vermogen',vraag:'Wat gebeurt er met de aflossingseis bij extra aflossen?',antwoord:`Voor eigenwoningschuld vanaf 2013 geldt een aflossingseis van 360 maanden annuïtair of lineair. Extra aflossen is toegestaan. Het aflosschema mag niet achterlopen op het fiscale schema. Controleer of het product na extra aflossing correct wordt aangepast.`,tags:['aflossingseis','extra aflossen','eigenwoningschuld'],bron:'Wet IB 2001'},
 {id:'kvx-211',thema:'krediet-vermogen',vraag:'Wat gebeurt er met de eigenwoningreserve bij verkoop en extra aflossen?',antwoord:`De eigenwoningreserve ontstaat bij verkoop met overwaarde. Die beperkt de nieuwe eigenwoningschuld als de klant binnen drie jaar een nieuwe woning koopt. Na drie jaar vervalt de reserve. Extra aflossen op de nieuwe schuld staat daar los van.`,tags:['eigenwoningreserve','verkoop','drie jaar'],bron:'Wet IB 2001'},
 {id:'kvx-212',thema:'krediet-vermogen',vraag:'Wanneer is sparen naast de hypotheek verstandig?',antwoord:`Sparen is verstandig als de buffer nog niet op orde is. Ook bij verwachte uitgaven is sparen vaak passend. Een klant met weinig vrij vermogen loopt meer risico bij tegenvallers. Leg uw beoordeling van de buffer vast.`,tags:['sparen','buffer','risico'],bron:''},
 {id:'kvx-213',thema:'krediet-vermogen',vraag:'Hoe ga ik om met een klant die al zijn spaargeld wil inzetten voor aflossing?',antwoord:`Wijs op het belang van een buffer. Laat zien hoe het budget eruitziet bij onverwachte uitgaven. De keuze ligt bij de klant. Leg vast dat u het risico heeft besproken en wat de klant heeft besloten.`,tags:['aflossing','buffer','klantkeuze'],bron:''},
 {id:'kvx-214',thema:'krediet-vermogen',vraag:'Is beleggen een alternatief voor extra aflossen?',antwoord:`Beleggen kan op lange termijn een hoger rendement geven, maar met risico. Aflossen geeft een zeker rentevoordeel. De keuze hangt af van risicobereidheid, horizon en kennis. Voor advies over beleggen gelden aparte Wft-eisen.`,tags:['beleggen','aflossen','risico'],bron:'Wft'},
 {id:'kvx-215',thema:'krediet-vermogen',vraag:'Welke Wft-eisen gelden voor advies over beleggen?',antwoord:`Advies over beleggingen valt onder aparte regels in de Wft en MiFID. De adviseur heeft daarvoor een passende vergunning en vakbekwaamheid nodig. Een hypotheekadviseur mag niet zomaar beleggingsadvies geven. Controleer uw vergunning en verwijs zo nodig door.`,tags:['Wft','beleggingsadvies','vergunning'],bron:'AFM'},
 {id:'kvx-216',thema:'krediet-vermogen',vraag:'Hoe leg ik een advies over aflossen of sparen vast?',antwoord:`Leg vast:
- de financiële situatie van de klant
- de besproken alternatieven
- de fiscale en financiële gevolgen
- de buffer en risico's
- de keuze van de klant en zijn motivatie
Zo kan het advies later worden gereconstrueerd.`,tags:['dossier','aflossen','sparen'],bron:''},
 {id:'kvx-217',thema:'krediet-vermogen',vraag:'Kan een klant extra afgelost geld later terugkrijgen?',antwoord:`Bij de meeste hypotheken is extra afgelost geld niet zomaar terug op te nemen. Er bestaan producten met een opnamemogelijkheid. Daarvoor gelden voorwaarden en opnieuw een toets. Controleer de voorwaarden van de geldverstrekker.`,tags:['opnemen','extra aflossen','flexibiliteit'],bron:''},
 {id:'kvx-218',thema:'krediet-vermogen',vraag:'Is de rente over een later opnieuw geleend bedrag aftrekbaar?',antwoord:`Dat hangt af van de besteding. Een nieuwe lening voor verbetering of onderhoud van de eigen woning kan eigenwoningschuld zijn. Een lening voor andere doelen niet. Leg de besteding vast en bewaar bewijs.`,tags:['opnieuw lenen','renteaftrek','besteding'],bron:'Wet IB 2001'},
 {id:'kvx-219',thema:'krediet-vermogen',vraag:'Hoe ga ik om met extra aflossen op een deel met overgangsrecht?',antwoord:`Extra aflossen op een deel met overgangsrecht verlaagt dat deel. Het resterende deel behoudt in de regel het overgangsrecht. Een later opnieuw geleend bedrag valt niet automatisch onder het overgangsrecht. Leg dit uit voordat de klant aflost.`,tags:['overgangsrecht','extra aflossen','eigenwoningschuld'],bron:'Wet IB 2001'},
 {id:'kvx-220',thema:'krediet-vermogen',vraag:'Op welk leningdeel kan de klant het beste extra aflossen?',antwoord:`Vaak ligt het voor de hand om af te lossen op het deel met de hoogste rente. Ook de fiscale status van het deel speelt een rol. Een box 3-deel heeft geen renteaftrek, wat aflossen extra aantrekkelijk kan maken. Laat de berekening zien en leg de keuze vast.`,tags:['leningdeel','extra aflossen','rente'],bron:''},
 {id:'kvx-221',thema:'krediet-vermogen',vraag:'Waarom is aflossen op een box 3-leningdeel vaak interessant?',antwoord:`De rente op een box 3-leningdeel is niet aftrekbaar. Aflossen bespaart dus de volle rente. Daarnaast vermindert het de box 3-schuld, wat alleen effect heeft boven de schuldendrempel. Neem dit mee in de afweging.`,tags:['box 3-leningdeel','aflossen','rente'],bron:'Wet IB 2001'},
 {id:'kvx-222',thema:'krediet-vermogen',vraag:'Hoe beoordeel ik de boetevrije ruimte voor extra aflossen?',antwoord:`Geldverstrekkers hanteren een jaarlijks boetevrij deel. Het percentage en de berekeningswijze verschillen. Soms is de ruimte niet overdraagbaar naar een volgend jaar. Controleer de voorwaarden van de geldverstrekker.`,tags:['boetevrij','extra aflossen','voorwaarden'],bron:''},
 {id:'kvx-223',thema:'krediet-vermogen',vraag:'Wat is het risico van spreiden van extra aflossingen over de jaarwisseling?',antwoord:`Spreiden over twee kalenderjaren kan de boetevrije ruimte beter benutten. Ook kan het effect hebben op box 3 door de peildatum. Wel moet de planning kloppen met de voorwaarden van de geldverstrekker. Leg de planning vast.`,tags:['spreiden','boetevrij','jaarwisseling'],bron:''},
 {id:'kvx-224',thema:'krediet-vermogen',vraag:'Wat is het verschil tussen sparen en beleggen in box 3?',antwoord:`Spaargeld en beleggingen vallen allebei in box 3. In het forfaitaire stelsel geldt voor beide een ander forfaitair rendement. Bij de tegenbewijsregeling telt het werkelijke rendement. Gebruik de actuele regels van de Belastingdienst.`,tags:['sparen','beleggen','box 3'],bron:'Belastingdienst'},
 {id:'kvx-225',thema:'krediet-vermogen',vraag:'Is een lijfrentevoorziening een alternatief voor extra aflossen?',antwoord:`Een lijfrente kan fiscaal voordelig zijn als er jaarruimte of reserveringsruimte is. Het geld is wel vastgezet voor een uitkering later. Extra aflossen geeft rentebesparing maar weinig flexibiliteit. Verwijs voor de jaarruimte naar de Belastingdienst.`,tags:['lijfrente','jaarruimte','aflossen'],bron:'Wet IB 2001'},
 {id:'kvx-226',thema:'krediet-vermogen',vraag:'Hoe ga ik om met de wens van een klant om schuldenvrij met pensioen te gaan?',antwoord:`Bekijk welke schuld er bij pensionering nog resteert. Vergelijk dat met het verwachte pensioeninkomen. Bespreek of extra aflossen of sparen daarbij helpt. Leg de doelstelling en het plan vast.`,tags:['pensioen','schuldenvrij','planning'],bron:''},
 {id:'kvx-227',thema:'krediet-vermogen',vraag:'Hoe bepaal ik of de hypotheek na pensionering betaalbaar is?',antwoord:`Maak een berekening met het verwachte pensioeninkomen en de resterende schuld. Gebruik een overzicht van de opgebouwde pensioenen. Houd rekening met wijzigingen in de fiscale situatie. Leg vast welke uitgangspunten u heeft gebruikt.`,tags:['pensioen','betaalbaarheid','berekening'],bron:''},
 {id:'kvx-228',thema:'krediet-vermogen',vraag:'Wat is een veelgemaakte fout bij advies over aflossen?',antwoord:`Veelgemaakte fouten zijn:
- geen rekening houden met de buffer
- verouderde fiscale cijfers gebruiken
- de boetevrije ruimte niet controleren
- vergeten dat afgelost geld niet terug op te nemen is
Werk met een vaste checklist.`,tags:['fouten','aflossen','checklist'],bron:''},
 {id:'kvx-229',thema:'krediet-vermogen',vraag:'Hoe ga ik om met een klant die wil aflossen om toeslagen te houden?',antwoord:`Het advies moet zijn gebaseerd op de totale financiële situatie. Het effect op toeslagen kan een factor zijn, maar niet het enige argument. Wijs op de risico's van een te kleine buffer. Leg de afweging vast.`,tags:['toeslagen','aflossen','afweging'],bron:''},
 {id:'kvx-230',thema:'krediet-vermogen',vraag:'Hoe beïnvloedt de rentevaste periode de keuze voor extra aflossen?',antwoord:`Bij een lage rente is de besparing door aflossen kleiner. Na afloop van de rentevaste periode kan de rente stijgen. Extra aflossen kan dan meer opleveren. Bespreek het moment van renteherziening in het advies.`,tags:['rentevaste periode','aflossen','renteherziening'],bron:''},
 {id:'kvx-231',thema:'krediet-vermogen',vraag:'Is aflossen bij een renteherziening boetevrij?',antwoord:`Op het moment van renteherziening kan de klant vaak boetevrij aflossen. Dat is een moment om de afweging opnieuw te maken. Controleer de voorwaarden van de geldverstrekker. Leg vast welke keuze is gemaakt.`,tags:['renteherziening','boetevrij','aflossen'],bron:''},
 {id:'kvx-232',thema:'krediet-vermogen',vraag:'Hoe ga ik om met een klant die verwacht te verhuizen?',antwoord:`Bij een verhuizing kan de hypotheek vaak worden afgelost of meegenomen. Extra aflossen vlak voor de verhuizing heeft dan minder effect. Bespreek de verhuisplannen. Leg de verwachtingen vast.`,tags:['verhuizen','aflossen','planning'],bron:''},
 {id:'kvx-233',thema:'krediet-vermogen',vraag:'Wat is het effect van extra aflossen op een overlijdensrisicoverzekering?',antwoord:`Een lagere schuld kan betekenen dat de verzekerde dekking hoger is dan nodig. Bij een gelijkblijvende dekking wordt dat verschil door extra aflossen groter. Bespreek of de dekking aangepast kan worden. Controleer de voorwaarden van de verzekeraar.`,tags:['ORV','dekking','aflossen'],bron:''},
 {id:'kvx-234',thema:'krediet-vermogen',vraag:'Hoe weeg ik het inflatierisico mee bij sparen?',antwoord:`Bij inflatie daalt de koopkracht van spaargeld. Een vaste hypotheekschuld daalt reëel ook in waarde. Dat maakt de afweging tussen sparen en aflossen genuanceerd. Leg uw uitgangspunten vast zonder te speculeren over cijfers.`,tags:['inflatie','sparen','koopkracht'],bron:''},
 {id:'kvx-235',thema:'krediet-vermogen',vraag:'Wat is een financiële planning in relatie tot hypotheekadvies?',antwoord:`Een financiële planning kijkt naar het totale vermogen en de doelen van de klant. Hypotheekadvies is daar een onderdeel van. Bij complexe situaties kan een financiële planner meerwaarde bieden. Bespreek dit met de klant.`,tags:['financiële planning','hypotheek','vermogen'],bron:''},
 {id:'kvx-236',thema:'krediet-vermogen',vraag:'Hoe ga ik om met een klant die zijn vermogen in een bv wil houden in plaats van aflossen?',antwoord:`Vermogen in een bv valt onder vennootschapsbelasting en box 2. De afweging met aflossen is complex. Verwijs naar de fiscalist van de klant. Leg vast dat u dit heeft gesignaleerd.`,tags:['bv','vermogen','aflossen'],bron:''},
 {id:'kvx-237',thema:'krediet-vermogen',vraag:'Wat is het effect van een hoge buffer op een acceptatie-aanvraag?',antwoord:`Een buffer is geen vereiste voor de toetsing, maar kan bij maatwerk wel meewegen. Sommige geldverstrekkers zien een buffer als compenserende factor. Controleer de voorwaarden van de geldverstrekker. Leg de buffer vast.`,tags:['buffer','maatwerk','acceptatie'],bron:''},
 {id:'kvx-238',thema:'krediet-vermogen',vraag:'Hoe ga ik om met een gift die een klant wil gebruiken voor aflossing?',antwoord:`Een schenking kan worden gebruikt voor aflossing. Dat verlaagt de schuld en de maandlast. Let op de fiscale gevolgen voor schenkbelasting en renteaftrek. Leg vast hoe de schenking is gebruikt.`,tags:['schenking','aflossing','fiscaal'],bron:''},
 {id:'kvx-239',thema:'krediet-vermogen',vraag:'Wat is de rol van de AOW-leeftijd bij aflossen of sparen?',antwoord:`Na het bereiken van de AOW-leeftijd daalt het inkomen vaak. De hypotheeklast moet dan nog betaalbaar zijn. Extra aflossen kan helpen, maar ook sparen voor de periode erna. Gebruik de actuele AOW-leeftijd en bedragen.`,tags:['AOW','pensioen','betaalbaarheid'],bron:'SVB'},
 {id:'kvx-240',thema:'krediet-vermogen',vraag:'Hoe ga ik om met een klant met een hoge spaarrente?',antwoord:`Bij een hoge spaarrente kan sparen tijdelijk meer opleveren. Spaarrentes kunnen echter snel wijzigen. De hypotheekrente staat vaak langer vast. Bespreek dit verschil en leg de afweging vast.`,tags:['spaarrente','sparen','aflossen'],bron:''},
 {id:'kvx-241',thema:'krediet-vermogen',vraag:'Wat moet ik weten over een opnamemogelijkheid bij een hypotheekproduct?',antwoord:`Sommige producten bieden de mogelijkheid om eerder afgelost bedrag opnieuw op te nemen. Daarvoor gelden voorwaarden en vaak een nieuwe toets. De fiscale status van het opnieuw opgenomen bedrag hangt af van de besteding. Controleer de voorwaarden van de geldverstrekker.`,tags:['opnamemogelijkheid','flexibiliteit','product'],bron:''},
 {id:'kvx-242',thema:'krediet-vermogen',vraag:'Wat is de relatie tussen vermogensopbouw en de NHG-voorwaarden?',antwoord:`NHG heeft voorwaarden voor de hoogte en de vorm van de lening. Vermogensopbouw buiten de hypotheek valt daar niet onder. Wel kan een buffer helpen bij betalingsproblemen. Controleer de actuele voorwaarden van NHG.`,tags:['NHG','vermogensopbouw','buffer'],bron:'NHG'},
 {id:'kvx-243',thema:'krediet-vermogen',vraag:'Hoe ga ik om met de wens om te sparen voor kinderen naast de hypotheek?',antwoord:`Sparen voor kinderen is een eigen doel. Het kan concurreren met aflossen of de buffer. Bespreek de prioriteiten. Leg de keuze vast.`,tags:['sparen voor kinderen','prioriteiten','budget'],bron:''},
 {id:'kvx-244',thema:'krediet-vermogen',vraag:'Hoe weeg ik de verduurzaming van de woning af tegen aflossen?',antwoord:`Verduurzaming kan de energielasten verlagen en de woningwaarde verhogen. Het kan dus een alternatief zijn voor aflossen. Bij aankoop of verbouwing gelden de leennormen voor verduurzaming. Maak een berekening en leg de keuze vast.`,tags:['verduurzaming','aflossen','energielasten'],bron:''},
 {id:'kvx-245',thema:'krediet-vermogen',vraag:'Hoeveel extra leenruimte geldt voor verduurzaming bij een woning met label C of D?',antwoord:`Volgens de leennormen 2026 van het Nibud geldt voor verduurzaming bij een woning met label C of D een extra leenruimte van €15.000. Bij label E, F of G is dat €20.000. Bij A of B en A+ of A++ is dat €10.000. Controleer of de geldverstrekker deze ruimte toepast.`,tags:['verduurzaming','energielabel','leenruimte'],bron:'Nibud'},
 {id:'kvx-246',thema:'krediet-vermogen',vraag:'Hoe ga ik om met een klant die extra wil lenen voor verduurzaming in plaats van aflossen?',antwoord:`Extra lenen voor verduurzaming kan de woonlasten verlagen. Tegelijk stijgt de schuld. Bekijk het netto-effect op het budget. Leg vast welke maatregelen worden genomen.`,tags:['verduurzaming','lenen','budget'],bron:''},
 {id:'kvx-247',thema:'krediet-vermogen',vraag:'Hoe beïnvloedt een tweede inkomen de afweging aflossen of sparen?',antwoord:`Volgens de leennormen 2026 telt een tweede inkomen volledig mee in de toetsing. Dat vergroot de leencapaciteit, maar ook het risico bij uitval van een inkomen. Een buffer kan dat risico opvangen. Bespreek het scenario van uitval.`,tags:['tweede inkomen','risico','buffer'],bron:'Nibud'},
 {id:'kvx-248',thema:'krediet-vermogen',vraag:'Wat is de rol van de alleenstaandencorrectie in de leennormen?',antwoord:`Volgens de leennormen 2026 geldt voor alleenstaanden een correctie van €17.000 in de berekening van de leencapaciteit. Dat vergroot de leencapaciteit. Het verandert niets aan de risico's van een enkel inkomen. Bespreek het belang van een buffer.`,tags:['alleenstaanden','leennormen','buffer'],bron:'Nibud'},
 {id:'kvx-249',thema:'krediet-vermogen',vraag:'Hoe ga ik om met een klant die door een restschuld niet kan sparen?',antwoord:`Een restschuld drukt op het budget. Voor restschulden in de periode 29 oktober 2012 tot en met 31 december 2017 kan een fiscale restschuldregeling gelden, met een maximale looptijd van 15 jaar. Bespreek een aflosplan. Leg de afspraken vast.`,tags:['restschuld','budget','aflosplan'],bron:'Wet IB 2001'},
 {id:'kvx-250',thema:'krediet-vermogen',vraag:'Hoe leg ik de uitkomst van een periodieke review over aflossen of sparen vast?',antwoord:`Leg de nieuwe situatie, de besproken opties en de keuze van de klant vast. Vermeld welke cijfers en bronnen u heeft gebruikt. Plan een volgend moment voor herbeoordeling. Zo blijft het dossier actueel.`,tags:['review','dossier','aflossen'],bron:''}
]);
